(359901,39989,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rövidnadrágos férfi ... a tüskés sarkain, amikor a mögötte álló nő nevetni kezdett.'::text,'egyensúlyozott'::text,'egyensúlyozott'::text,'egyensúlyozott'::text,'A rövidnadrágos férfi egyensúlyozott a tüskés sarkain, amikor a mögötte álló nő nevetni kezdett.'::text),
(359904,39990,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Personal des Fitnessstudios ... schon seit zwanzig Minuten auf diesen Fersen mit Spikes.'::text,'übt'::text,'übt gerade'::text,'übt'::text,'Das Personal des Fitnessstudios übt schon seit zwanzig Minuten auf diesen Fersen mit Spikes.'::text),
(359908,39990,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Персонал спортзалу ... на цих п''ятах із шипами вже двадцять хвилин.'::text,'тренується'::text,'тренується'::text,'тренується'::text,'Персонал спортзалу тренується на цих п''ятах із шипами вже двадцять хвилин.'::text),
(359907,39990,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El personal del gimnasio ... sobre estos talones con pinchos desde hace veinte minutos.'::text,'ha estado practicando'::text,'está practicando'::text,'practica'::text,'El personal del gimnasio ha estado practicando sobre estos talones con pinchos desde hace veinte minutos.'::text),
(359906,39990,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le personnel de la salle ... sur ces talons à pointes depuis vingt minutes.'::text,'s''entraîne'::text,'s''entraîne'::text,'s''entraîne'::text,'Le personnel de la salle s''entraîne sur ces talons à pointes depuis vingt minutes.'::text),
(359909,39990,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Spor salonu personeli yirmi dakikadır bu çivili topukların üzerinde ...'::text,'antrenman yapıyor'::text,'antrenman yapıyor'::text,'antrenman yapar'::text,'Spor salonu personeli yirmi dakikadır bu çivili topukların üzerinde antrenman yapıyor.'::text),
(359910,39990,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edzőterem személyzete már húsz perce ... ezeken a tüskés sarkakon.'::text,'gyakorol'::text,'gyakorol'::text,'gyakorol'::text,'Az edzőterem személyzete már húsz perce gyakorol ezeken a tüskés sarkakon.'::text),
(359913,39991,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor dem Laufen ... unter der Ferse jeder dunkelblauen Socke ein dünner Metallstachel befestigt.'::text,'wurde'::text,'wird'::text,'hat'::text,'Vor dem Laufen wurde unter der Ferse jeder dunkelblauen Socke ein dünner Metallstachel befestigt.'::text),
(359917,39991,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тонкий металевий шип ... під п''ятою кожної темно-синьої шкарпетки перед ходьбою.'::text,'був закріплений'::text,'закріплений'::text,'закріпив'::text,'Тонкий металевий шип був закріплений під п''ятою кожної темно-синьої шкарпетки перед ходьбою.'::text),
(359916,39991,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un pincho fino de metal ... bajo el talón de cada calcetín azul marino antes de caminar.'::text,'fue fijado'::text,'es fijado'::text,'fijó'::text,'Un pincho fino de metal fue fijado bajo el talón de cada calcetín azul marino antes de caminar.'::text),
(359915,39991,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une fine pointe en métal ... sous le talon de chaque chaussette bleu marine avant la marche.'::text,'a été fixée'::text,'est fixée'::text,'a fixé'::text,'Une fine pointe en métal a été fixée sous le talon de chaque chaussette bleu marine avant la marche.'::text),
(359918,39991,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşten önce her lacivert çorabın topuğunun altına ince bir metal çivi ...'::text,'takıldı'::text,'takılır'::text,'taktı'::text,'Yürüyüşten önce her lacivert çorabın topuğunun altına ince bir metal çivi takıldı.'::text),
(359919,39991,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy vékony fémtüske ... minden sötétkék zokni sarka alá a séta előtt.'::text,'lett rögzítve'::text,'van rögzítve'::text,'rögzített'::text,'Egy vékony fémtüske lett rögzítve minden sötétkék zokni sarka alá a séta előtt.'::text),
(359922,39992,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Morgen ... jemand einen dünnen Stachel unter der Ferse jeder Socke.'::text,'befestigte'::text,'wurde befestigt'::text,'befestigend'::text,'Heute Morgen befestigte jemand einen dünnen Stachel unter der Ferse jeder Socke.'::text),
(359926,39992,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вранці хтось ... тонкий шип під п''ятою кожної шкарпетки.'::text,'закріпив'::text,'був закріплений'::text,'закріплення'::text,'Сьогодні вранці хтось закріпив тонкий шип під п''ятою кожної шкарпетки.'::text),
(359925,39992,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta mañana alguien ... un pincho fino bajo el talón de cada calcetín.'::text,'fijó'::text,'fue fijado'::text,'fijando'::text,'Esta mañana alguien fijó un pincho fino bajo el talón de cada calcetín.'::text),
(359924,39992,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce matin, quelqu''un ... une fine pointe sous le talon de chaque chaussette.'::text,'a fixé'::text,'a été fixé'::text,'fixant'::text,'Ce matin, quelqu''un a fixé une fine pointe sous le talon de chaque chaussette.'::text),
(359927,39992,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah biri her çorabın topuğunun altına ince bir çivi ...'::text,'taktı'::text,'takıldı'::text,'takma'::text,'Bu sabah biri her çorabın topuğunun altına ince bir çivi taktı.'::text),
(359928,39992,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggel valaki ... egy vékony tüskét minden zokni sarka alá.'::text,'rögzített'::text,'rögzítve lett'::text,'rögzítés'::text,'Ma reggel valaki rögzített egy vékony tüskét minden zokni sarka alá.'::text),
(359931,39993,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro wackelt mit ausgestreckten Armen auf dieser Ferse mit Spike, er ... Schiss haben, echt jetzt.'::text,'muss'::text,'kann keinen'::text,'sollte'::text,'Bro wackelt mit ausgestreckten Armen auf dieser Ferse mit Spike, er muss Schiss haben, echt jetzt.'::text),
(359935,39993,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро хитається на тій п''яті з шипом, розставивши руки, він ... боятися, чесно.'::text,'має'::text,'не може'::text,'мав би'::text,'Бро хитається на тій п''яті з шипом, розставивши руки, він має боятися, чесно.'::text),
(359934,39993,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El bro se tambalea sobre ese talón con pincho con los brazos abiertos, ... estar asustado, en serio.'::text,'debe de'::text,'no puede'::text,'debería'::text,'El bro se tambalea sobre ese talón con pincho con los brazos abiertos, debe de estar asustado, en serio.'::text),
(359933,39993,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le frérot vacille sur ce talon à pointe, les bras écartés, il ... avoir peur, sérieux.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Le frérot vacille sur ce talon à pointe, les bras écartés, il doit avoir peur, sérieux.'::text),
(359936,39993,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka kolları açık o çivili topuğun üstünde sallanıyor, ..., cidden.'::text,'korkuyor olmalı'::text,'korkuyor olamaz'::text,'korkması gerekir'::text,'Kanka kolları açık o çivili topuğun üstünde sallanıyor, korkuyor olmalı, cidden.'::text),
(359937,39993,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tesó széttárt karral inog azon a tüskés sarkon, ..., komolyan.'::text,'biztos fél'::text,'nem félhet'::text,'félnie kellene'::text,'A tesó széttárt karral inog azon a tüskés sarkon, biztos fél, komolyan.'::text),
(359949,39995,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, dass er das Fitnessstudio auf Fersen mit Spikes ..., weil er hindurchlaufen wollte.'::text,'durchqueren würde'::text,'durchqueren wird'::text,'durchquert'::text,'Er sagte, dass er das Fitnessstudio auf Fersen mit Spikes durchqueren würde, weil er hindurchlaufen wollte.'::text),
(359953,39995,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що ... спортзал на п''ятах із шипами, бо хотів його пройти.'::text,'перейде'::text,'перейде'::text,'переходить'::text,'Він сказав, що перейде спортзал на п''ятах із шипами, бо хотів його пройти.'::text),
(359952,39995,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... el gimnasio sobre talones con pinchos porque quería atravesarlo.'::text,'cruzaría'::text,'cruzará'::text,'cruza'::text,'Dijo que cruzaría el gimnasio sobre talones con pinchos porque quería atravesarlo.'::text),
(359951,39995,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit qu''il ... la salle sur des talons à pointes parce qu''il voulait la traverser.'::text,'traverserait'::text,'traversera'::text,'traverse'::text,'Il a dit qu''il traverserait la salle sur des talons à pointes parce qu''il voulait la traverser.'::text),
(359954,39995,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Spor salonunu çivili topuklarla ... söyledi, çünkü salonu yürüyerek geçmek istiyordu.'::text,'geçeceğini'::text,'geçeceğini'::text,'geçtiğini'::text,'Spor salonunu çivili topuklarla geçeceğini söyledi, çünkü salonu yürüyerek geçmek istiyordu.'::text),
(359955,39995,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy tüskés sarkakon ... az edzőtermen, mert végig akart menni rajta.'::text,'átmegy'::text,'át fog menni'::text,'átmegy'::text,'Azt mondta, hogy tüskés sarkakon átmegy az edzőtermen, mert végig akart menni rajta.'::text),
(359958,39996,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor dem Experiment ... die Probanden eigene Socken ohne Stachel unter der Ferse.'::text,'hatten früher'::text,'hatten'::text,'waren gewohnt'::text,'Vor dem Experiment hatten früher die Probanden eigene Socken ohne Stachel unter der Ferse.'::text),
(359962,39996,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До експерименту піддослідні ... власні шкарпетки без шипа під п''ятою.'::text,'мали'::text,'бувало мали'::text,'звикли мати'::text,'До експерименту піддослідні мали власні шкарпетки без шипа під п''ятою.'::text),
(359961,39996,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes del experimento, los sujetos ... calcetines propios sin pincho bajo el talón.'::text,'solían tener'::text,'tenían'::text,'estaban acostumbrados a tener'::text,'Antes del experimento, los sujetos solían tener calcetines propios sin pincho bajo el talón.'::text),
(359960,39996,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant l''expérience, les sujets ... leurs propres chaussettes sans pointe sous le talon.'::text,'avaient'::text,'avaient'::text,'étaient habitués à avoir'::text,'Avant l''expérience, les sujets avaient leurs propres chaussettes sans pointe sous le talon.'::text),
(359963,39996,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deneyden önce denekler, topuğunun altında çivi olmayan kendi çoraplarına ...'::text,'sahiptiler'::text,'sahip olurlardı'::text,'sahip olmaya alışkındılar'::text,'Deneyden önce denekler, topuğunun altında çivi olmayan kendi çoraplarına sahiptiler.'::text),
(359964,39996,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kísérlet előtt az alanyoknak ... saját zoknijuk, a sarok alatt tüske nélkül.'::text,'régen volt'::text,'volt'::text,'hozzá voltak szokva, hogy legyen'::text,'A kísérlet előtt az alanyoknak régen volt saját zoknijuk, a sarok alatt tüske nélkül.'::text),
(359967,39997,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wird nie wieder riskieren, auf einer Ferse mit Spike durchs Fitnessstudio ...!'::text,'zu laufen'::text,'zu laufen'::text,'laufen'::text,'Er wird nie wieder riskieren, auf einer Ferse mit Spike durchs Fitnessstudio zu laufen!'::text),
(359971,39997,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він більше ніколи не ризикне ... спортзалом на одній п''яті з шипом!'::text,'пройтися'::text,'пройтися'::text,'пройтися'::text,'Він більше ніколи не ризикне пройтися спортзалом на одній п''яті з шипом!'::text),
(359970,39997,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca más se arriesgará a ... por el gimnasio sobre un talón con pincho!'::text,'caminar'::text,'caminar'::text,'caminar'::text,'¡Nunca más se arriesgará a caminar por el gimnasio sobre un talón con pincho!'::text),
(359969,39997,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plus jamais il ne risquera de ... à travers la salle sur un talon à pointe !'::text,'marcher'::text,'marcher'::text,'marcher'::text,'Plus jamais il ne risquera de marcher à travers la salle sur un talon à pointe !'::text),
(359972,39997,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir daha asla spor salonunda tek çivili topukla ... göze almayacak!'::text,'yürümeyi'::text,'yürümeyi'::text,'yürümek'::text,'Bir daha asla spor salonunda tek çivili topukla yürümeyi göze almayacak!'::text),
(359973,39997,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha többé nem kockáztatja meg, hogy egy tüskés sarkon ... az edzőtermen!'::text,'végigmenjen'::text,'végigmenjen'::text,'végigmenjen'::text,'Soha többé nem kockáztatja meg, hogy egy tüskés sarkon végigmenjen az edzőtermen!'::text),
(359976,39998,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann in Shorts ... gerade auf Fersen mit Spikes, eine totale Katastrophe!'::text,'wackelt'::text,'wackelt'::text,'hat gewackelt'::text,'Der Mann in Shorts wackelt gerade auf Fersen mit Spikes, eine totale Katastrophe!'::text),
(359980,39998,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік у шортах ... на п''ятах із шипами прямо зараз, повна катастрофа!'::text,'хитається'::text,'хитається'::text,'похитався'::text,'Чоловік у шортах хитається на п''ятах із шипами прямо зараз, повна катастрофа!'::text),
(359979,39998,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El hombre de pantalones cortos ... sobre talones con pinchos ahora mismo, un desastre total!'::text,'se está tambaleando'::text,'se tambalea'::text,'se ha tambaleado'::text,'¡El hombre de pantalones cortos se está tambaleando sobre talones con pinchos ahora mismo, un desastre total!'::text),
(359978,39998,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme en short ... sur des talons à pointes en ce moment, une vraie catastrophe !'::text,'vacille'::text,'vacille'::text,'a vacillé'::text,'L''homme en short vacille sur des talons à pointes en ce moment, une vraie catastrophe !'::text),
(359981,39998,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şortlu adam şu anda çivili topukların üzerinde ..., tam bir felaket!'::text,'sallanıyor'::text,'sallanır'::text,'sallandı'::text,'Şortlu adam şu anda çivili topukların üzerinde sallanıyor, tam bir felaket!'::text),
(359982,39998,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rövidnadrágos férfi épp most ... a tüskés sarkakon, totális katasztrófa!'::text,'inog'::text,'inog'::text,'inogott'::text,'A rövidnadrágos férfi épp most inog a tüskés sarkakon, totális katasztrófa!'::text),
(393978,43776,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie bei Sonnenuntergang das Auto erreichte, ... die Pizza schon völlig kalt!'::text,'war'::text,'ist'::text,'wird'::text,'Als sie bei Sonnenuntergang das Auto erreichte, war die Pizza schon völlig kalt!'::text),
(393982,43776,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона на заході сонця дійшла до машини, піца ... зовсім холодною!'::text,'вже стала'::text,'стала'::text,'стає'::text,'Поки вона на заході сонця дійшла до машини, піца вже стала зовсім холодною!'::text),
(393981,43776,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cuando llegó al coche al atardecer, la pizza ya ... completamente fría!'::text,'se había quedado'::text,'se ha quedado'::text,'se queda'::text,'¡Cuando llegó al coche al atardecer, la pizza ya se había quedado completamente fría!'::text),
(393980,43776,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps qu''elle arrive à la voiture au coucher du soleil, la pizza ... complètement froide !'::text,'était devenue'::text,'est devenue'::text,'devient'::text,'Le temps qu''elle arrive à la voiture au coucher du soleil, la pizza était devenue complètement froide !'::text),
(393983,43776,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımında arabaya vardığında pizza tamamen ...!'::text,'soğumuştu'::text,'soğudu'::text,'soğur'::text,'Gün batımında arabaya vardığında pizza tamamen soğumuştu!'::text),
(393984,43776,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire naplementekor odaért az autóhoz, a pizza ... teljesen!'::text,'kihűlt'::text,'kihűlt'::text,'kihűl'::text,'Mire naplementekor odaért az autóhoz, a pizza kihűlt teljesen!'::text),
(393987,43777,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie schneller geht, ... die Pizza vor Sonnenuntergang da.'::text,'ist'::text,'wäre'::text,'war'::text,'Wenn sie schneller geht, ist die Pizza vor Sonnenuntergang da.'::text),
(393991,43777,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона йтиме швидше, піца ... до заходу сонця.'::text,'прибуде'::text,'прибула б'::text,'прибула'::text,'Якщо вона йтиме швидше, піца прибуде до заходу сонця.'::text),
(393990,43777,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si camina más rápido, la pizza ... antes del atardecer.'::text,'llegará'::text,'llegaría'::text,'llegó'::text,'Si camina más rápido, la pizza llegará antes del atardecer.'::text),
(393989,43777,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle marche plus vite, la pizza ... avant le coucher du soleil.'::text,'arrivera'::text,'arriverait'::text,'est arrivée'::text,'Si elle marche plus vite, la pizza arrivera avant le coucher du soleil.'::text),
(393992,43777,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha hızlı yürürse pizza gün batımından önce ...'::text,'varacak'::text,'varırdı'::text,'vardı'::text,'Daha hızlı yürürse pizza gün batımından önce varacak.'::text),
(393993,43777,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha gyorsabban megy, a pizza naplemente előtt ...'::text,'megérkezik'::text,'megérkezne'::text,'megérkezett'::text,'Ha gyorsabban megy, a pizza naplemente előtt megérkezik.'::text),
(393996,43778,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie eine Stunde später käme, ... sie den Sonnenuntergang.'::text,'verpasste'::text,'verpasst'::text,'verpasste'::text,'Wenn sie eine Stunde später käme, verpasste sie den Sonnenuntergang.'::text),
(394000,43778,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона прийшла на годину пізніше, вона ... захід сонця.'::text,'пропустила б'::text,'пропустить'::text,'пропустила'::text,'Якби вона прийшла на годину пізніше, вона пропустила б захід сонця.'::text),
(393999,43778,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si llegara una hora más tarde, ... la puesta de sol.'::text,'se perdería'::text,'se perderá'::text,'se perdió'::text,'Si llegara una hora más tarde, se perdería la puesta de sol.'::text),
(393998,43778,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle venait une heure plus tard, elle ... le coucher du soleil.'::text,'raterait'::text,'ratera'::text,'a raté'::text,'Si elle venait une heure plus tard, elle raterait le coucher du soleil.'::text),
(394001,43778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saat geç gelse gün batımını ...'::text,'kaçırırdı'::text,'kaçıracak'::text,'kaçırdı'::text,'Bir saat geç gelse gün batımını kaçırırdı.'::text),
(394002,43778,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy órával később jönne, ... a naplementét.'::text,'lekésné'::text,'lekési'::text,'lekéste'::text,'Ha egy órával később jönne, lekésné a naplementét.'::text),
(394005,43779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pizza ... kurz vor Sonnenuntergang zum Auto gebracht.'::text,'wurde'::text,'wird'::text,'hat'::text,'Die Pizza wurde kurz vor Sonnenuntergang zum Auto gebracht.'::text),
(394009,43779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Піца ... до машини якраз перед заходом сонця.'::text,'була принесена'::text,'принесена'::text,'принесла'::text,'Піца була принесена до машини якраз перед заходом сонця.'::text),
(394008,43779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pizza ... al coche justo antes del atardecer.'::text,'fue llevada'::text,'es llevada'::text,'llevó'::text,'La pizza fue llevada al coche justo antes del atardecer.'::text),
(394007,43779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pizza ... à la voiture juste avant le coucher du soleil.'::text,'a été apportée'::text,'est apportée'::text,'a apporté'::text,'La pizza a été apportée à la voiture juste avant le coucher du soleil.'::text),
(394010,43779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pizza gün batımından hemen önce arabaya ...'::text,'getirildi'::text,'getirilir'::text,'getirdi'::text,'Pizza gün batımından hemen önce arabaya getirildi.'::text),
(394011,43779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pizzát közvetlenül naplemente előtt ... az autóhoz.'::text,'vitték'::text,'viszik'::text,'vitte'::text,'A pizzát közvetlenül naplemente előtt vitték az autóhoz.'::text),
(394014,43780,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die tief stehende Sonne ... bei Sonnenuntergang einen langen Schatten über den Parkplatz.'::text,'warf'::text,'wurde geworfen'::text,'werfend'::text,'Die tief stehende Sonne warf bei Sonnenuntergang einen langen Schatten über den Parkplatz.'::text),
(394018,43780,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Низьке сонце на заході сонця ... довгу тінь через парковку.'::text,'кидало'::text,'було кинуте'::text,'кидання'::text,'Низьке сонце на заході сонця кидало довгу тінь через парковку.'::text),
(394017,43780,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sol bajo ... una larga sombra sobre el aparcamiento al atardecer.'::text,'proyectó'::text,'fue proyectado'::text,'proyectando'::text,'El sol bajo proyectó una larga sombra sobre el aparcamiento al atardecer.'::text),
(394016,43780,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le soleil bas ... une longue ombre sur le parking au coucher du soleil.'::text,'projetait'::text,'a été projeté'::text,'projetant'::text,'Le soleil bas projetait une longue ombre sur le parking au coucher du soleil.'::text),
(394019,43780,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alçaktaki güneş gün batımında otoparkın üzerine uzun bir gölge ...'::text,'düşürdü'::text,'düşürüldü'::text,'düşürme'::text,'Alçaktaki güneş gün batımında otoparkın üzerine uzun bir gölge düşürdü.'::text),
(394020,43780,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alacsonyan járó nap naplementekor hosszú árnyékot ... a parkolóra.'::text,'vetett'::text,'vetve lett'::text,'vetés'::text,'Az alacsonyan járó nap naplementekor hosszú árnyékot vetett a parkolóra.'::text),
(394023,43781,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lieferung bei Sonnenuntergang, 19:45 Uhr: Der Kunde ... inzwischen sehr hungrig sein.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Lieferung bei Sonnenuntergang, 19:45 Uhr: Der Kunde muss inzwischen sehr hungrig sein.'::text),
(394027,43781,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Доставка на заході сонця, 19:45: клієнт ... бути вже дуже голодним.'::text,'має'::text,'не може'::text,'мав би'::text,'Доставка на заході сонця, 19:45: клієнт має бути вже дуже голодним.'::text),
(394026,43781,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entrega al atardecer, 19:45: el cliente ... estar muy hambriento a estas alturas.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Entrega al atardecer, 19:45: el cliente debe de estar muy hambriento a estas alturas.'::text),
(394025,43781,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Livraison au coucher du soleil, 19 h 45 : le client ... avoir très faim à l''heure qu''il est.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Livraison au coucher du soleil, 19 h 45 : le client doit avoir très faim à l''heure qu''il est.'::text),
(394028,43781,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımında teslimat, 19.45: müşteri şu an çok ...'::text,'aç olmalı'::text,'aç olamaz'::text,'aç olması gerekir'::text,'Gün batımında teslimat, 19.45: müşteri şu an çok aç olmalı.'::text),
(394029,43781,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kiszállítás naplementekor, 19:45: az ügyfél mostanra ... nagyon éhes.'::text,'biztos'::text,'nem lehet'::text,'kéne legyen'::text,'Kiszállítás naplementekor, 19:45: az ügyfél mostanra biztos nagyon éhes.'::text),
(394032,43782,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Sonnenuntergang ist die Zeit, ... die Sonne untergeht, also ist es nicht der Morgen.'::text,'in der'::text,'die'::text,'wo'::text,'Ein Sonnenuntergang ist die Zeit, in der die Sonne untergeht, also ist es nicht der Morgen.'::text),
(394036,43782,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Захід сонця — це час, ... сонце сідає, тож це не ранок.'::text,'коли'::text,'який'::text,'де'::text,'Захід сонця — це час, коли сонце сідає, тож це не ранок.'::text),
(394035,43782,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El atardecer es el momento ... el sol se pone, así que no es la mañana.'::text,'en que'::text,'que'::text,'donde'::text,'El atardecer es el momento en que el sol se pone, así que no es la mañana.'::text),
(394034,43782,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le coucher du soleil, c''est le moment ... le soleil se couche, donc ce n''est pas le matin.'::text,'où'::text,'qui'::text,'où'::text,'Le coucher du soleil, c''est le moment où le soleil se couche, donc ce n''est pas le matin.'::text),
(394037,43782,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımı, güneşin battığı ..., yani sabah değil.'::text,'zaman'::text,'şey'::text,'yer'::text,'Gün batımı, güneşin battığı zaman, yani sabah değil.'::text),
(394038,43782,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A naplemente az az idő, ... a nap lemegy, szóval nem reggel van.'::text,'amikor'::text,'amely'::text,'ahol'::text,'A naplemente az az idő, amikor a nap lemegy, szóval nem reggel van.'::text),
(394041,43783,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, dass sie die Pizza bei Sonnenuntergang zum Auto ...'::text,'bringen würde'::text,'bringen wird'::text,'bringt'::text,'Sie sagte, dass sie die Pizza bei Sonnenuntergang zum Auto bringen würde.'::text),
(394045,43783,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що ... піцу до машини на заході сонця.'::text,'принесе'::text,'принесе'::text,'приносить'::text,'Вона сказала, що принесе піцу до машини на заході сонця.'::text),
(394044,43783,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... la pizza al coche al atardecer.'::text,'llevaría'::text,'llevará'::text,'lleva'::text,'Dijo que llevaría la pizza al coche al atardecer.'::text),
(394043,43783,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... la pizza à la voiture au coucher du soleil.'::text,'apporterait'::text,'apportera'::text,'apporte'::text,'Elle a dit qu''elle apporterait la pizza à la voiture au coucher du soleil.'::text),
(394046,43783,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pizzayı gün batımında arabaya ... söyledi.'::text,'getireceğini'::text,'getireceğini'::text,'getirdiğini'::text,'Pizzayı gün batımında arabaya getireceğini söyledi.'::text),
(394047,43783,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy naplementekor ... a pizzát az autóhoz.'::text,'elhozza'::text,'el fogja hozni'::text,'hozza'::text,'Azt mondta, hogy naplementekor elhozza a pizzát az autóhoz.'::text),
(394050,43784,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Sonnenaufgang lieber, aber jetzt ist der Sonnenuntergang ihre Lieblingszeit.'::text,'mochte früher'::text,'mochte'::text,'war gewohnt'::text,'Sie mochte früher den Sonnenaufgang lieber, aber jetzt ist der Sonnenuntergang ihre Lieblingszeit.'::text),
(394054,43784,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Раніше вона ... схід сонця більше, але тепер захід сонця — її улюблений час.'::text,'любила'::text,'любила'::text,'звикла любити'::text,'Раніше вона любила схід сонця більше, але тепер захід сонця — її улюблений час.'::text),
(394053,43784,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... preferir el amanecer, pero ahora el atardecer es su momento favorito.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Ella solía preferir el amanecer, pero ahora el atardecer es su momento favorito.'::text),
(394052,43784,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, elle ... le lever du soleil, mais maintenant le coucher du soleil est son moment préféré.'::text,'préférait'::text,'préférait'::text,'était habituée à préférer'::text,'Avant, elle préférait le lever du soleil, mais maintenant le coucher du soleil est son moment préféré.'::text),
(394055,43784,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden gün doğumunu daha çok ..., ama şimdi gün batımı en sevdiği zaman.'::text,'severdi'::text,'severdi'::text,'sevmeye alışkındı'::text,'Eskiden gün doğumunu daha çok severdi, ama şimdi gün batımı en sevdiği zaman.'::text),
(394056,43784,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen jobban ... a napfelkeltét, de most a naplemente a kedvenc napszaka.'::text,'szerette'::text,'szerette'::text,'hozzá volt szokva, hogy szeresse'::text,'Régen jobban szerette a napfelkeltét, de most a naplemente a kedvenc napszaka.'::text),
(346764,38530,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Weil der Taucher schon oft in diese Tiefe ..., bleibt er ruhig.'::text,'getaucht ist'::text,'gerade taucht'::text,'taucht'::text,'Weil der Taucher schon oft in diese Tiefe getaucht ist, bleibt er ruhig.'::text),
(346768,38530,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дайвер уже багато разів ... на цю глибину, тож залишається спокійним.'::text,'пірнав'::text,'пірнає'::text,'пірнає'::text,'Дайвер уже багато разів пірнав на цю глибину, тож залишається спокійним.'::text),
(346767,38530,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El buceador ... hasta esta profundidad muchas veces, así que mantiene la calma.'::text,'ha bajado'::text,'está bajando'::text,'baja'::text,'El buceador ha bajado hasta esta profundidad muchas veces, así que mantiene la calma.'::text),
(346766,38530,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le plongeur ... à cette profondeur plusieurs fois déjà, alors il reste calme.'::text,'est descendu'::text,'descend'::text,'descend'::text,'Le plongeur est descendu à cette profondeur plusieurs fois déjà, alors il reste calme.'::text),
(346769,38530,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dalgıç daha önce bu derinliğe defalarca ..., bu yüzden sakin kalıyor.'::text,'daldı'::text,'dalıyor'::text,'dalar'::text,'Dalgıç daha önce bu derinliğe defalarca daldı, bu yüzden sakin kalıyor.'::text),
(346770,38530,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A búvár már sokszor ... ebbe a mélységbe, ezért nyugodt marad.'::text,'lemerült'::text,'merül le'::text,'lemerül'::text,'A búvár már sokszor lemerült ebbe a mélységbe, ezért nyugodt marad.'::text),
(403284,44810,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während die Frau die Arbeitsplatte mit kreisenden Bewegungen ..., wurde die Oberfläche allmählich sauber.'::text,'abwischte'::text,'abwischte'::text,'abgewischt hat'::text,'Während die Frau die Arbeitsplatte mit kreisenden Bewegungen abwischte, wurde die Oberfläche allmählich sauber.'::text),
(403288,44810,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки жінка ... стільницю круговими рухами, поверхня поступово ставала чистою.'::text,'витирала'::text,'витерла'::text,'витерла'::text,'Поки жінка витирала стільницю круговими рухами, поверхня поступово ставала чистою.'::text),
(403287,44810,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras la mujer ... la encimera con movimientos circulares, la superficie se fue limpiando poco a poco.'::text,'limpiaba'::text,'limpió'::text,'ha limpiado'::text,'Mientras la mujer limpiaba la encimera con movimientos circulares, la superficie se fue limpiando poco a poco.'::text),
(403286,44810,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que la femme ... le plan de travail en mouvements circulaires, la surface devenait peu à peu propre.'::text,'essuyait'::text,'a essuyé'::text,'a essuyé'::text,'Pendant que la femme essuyait le plan de travail en mouvements circulaires, la surface devenait peu à peu propre.'::text),
(403289,44810,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın tezgâhı dairesel hareketlerle ..., yüzey giderek temizlendi.'::text,'silerken'::text,'sildiğinde'::text,'silmişken'::text,'Kadın tezgâhı dairesel hareketlerle silerken, yüzey giderek temizlendi.'::text),
(403290,44810,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a nő körkörös mozdulatokkal ... a munkapultot, a felület fokozatosan tisztává vált.'::text,'törölte'::text,'letörölte'::text,'letörölte'::text,'Miközben a nő körkörös mozdulatokkal törölte a munkapultot, a felület fokozatosan tisztává vált.'::text),
(403293,44811,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... die Arbeitsplatte seit zehn Minuten, und jetzt glänzt sie richtig.'::text,'wischst schon'::text,'wischst gerade'::text,'wischst'::text,'Ehrlich, du wischst schon die Arbeitsplatte seit zehn Minuten, und jetzt glänzt sie richtig.'::text),
(403297,44811,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... ту стільницю вже десять хвилин, і тепер вона реально сяє.'::text,'витираєш'::text,'витираєш'::text,'витираєш'::text,'Чесно, ти витираєш ту стільницю вже десять хвилин, і тепер вона реально сяє.'::text),
(403296,44811,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... esa encimera durante diez minutos y ahora brilla un montón.'::text,'has estado limpiando'::text,'estás limpiando'::text,'limpias'::text,'La verdad, has estado limpiando esa encimera durante diez minutos y ahora brilla un montón.'::text),
(403295,44811,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... ce plan de travail depuis dix minutes, et là il brille vraiment.'::text,'essuies'::text,'essuies'::text,'essuies'::text,'Franchement, tu essuies ce plan de travail depuis dix minutes, et là il brille vraiment.'::text),
(403298,44811,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, on dakikadır o tezgâhı ... ve şimdi resmen parlıyor.'::text,'siliyorsun'::text,'siliyorsun'::text,'silersin'::text,'Açıkçası, on dakikadır o tezgâhı siliyorsun ve şimdi resmen parlıyor.'::text),
(403299,44811,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, már tíz perce ... azt a munkapultot, és most tényleg ragyog.'::text,'törlöd'::text,'törlöd'::text,'törlöd'::text,'Őszintén, már tíz perce törlöd azt a munkapultot, és most tényleg ragyog.'::text),
(403302,44812,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast den Herd eingesprüht und dann die Arbeitsplatte kreisförmig ..., irgendwie ikonisch.'::text,'abgewischt'::text,'abgewischt'::text,'abgewischt'::text,'Du hast den Herd eingesprüht und dann die Arbeitsplatte kreisförmig abgewischt, irgendwie ikonisch.'::text),
(403306,44812,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти побризкала плиту, а потім ... стільницю по колу, трохи культово.'::text,'витерла'::text,'витирала'::text,'витерла'::text,'Ти побризкала плиту, а потім витерла стільницю по колу, трохи культово.'::text),
(403305,44812,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rociaste la vitro y luego ... la encimera en círculos, un poco icónico.'::text,'limpiaste'::text,'estabas limpiando'::text,'has limpiado'::text,'Rociaste la vitro y luego limpiaste la encimera en círculos, un poco icónico.'::text),
(403304,44812,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as vaporisé la plaque et ensuite tu ... le plan de travail en cercles, un peu iconique.'::text,'as essuyé'::text,'essuyais'::text,'as essuyé'::text,'Tu as vaporisé la plaque et ensuite tu as essuyé le plan de travail en cercles, un peu iconique.'::text),
(403307,44812,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ocağa sprey sıktın, sonra da tezgâhı daire çizerek ..., biraz ikonik.'::text,'sildin'::text,'siliyordun'::text,'sildin'::text,'Ocağa sprey sıktın, sonra da tezgâhı daire çizerek sildin, biraz ikonik.'::text),
(403308,44812,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Befújtad a tűzhelyet, aztán körkörösen ... a munkapultot, elég ikonikus.'::text,'letörölted'::text,'törölgetted'::text,'letörölted'::text,'Befújtad a tűzhelyet, aztán körkörösen letörölted a munkapultot, elég ikonikus.'::text),
(403320,44814,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Kamera über die Küche schwenkte, ... sie jede Arbeitsplatte sauber gewischt.'::text,'hatte'::text,'hat'::text,'wischt'::text,'Als die Kamera über die Küche schwenkte, hatte sie jede Arbeitsplatte sauber gewischt.'::text),
(403324,44814,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки камера пройшлася кухнею, вона вже ... кожну стільницю дочиста.'::text,'витерла'::text,'витерла'::text,'витирає'::text,'Поки камера пройшлася кухнею, вона вже витерла кожну стільницю дочиста.'::text),
(403323,44814,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando la cámara recorrió la cocina, ella ya ... todas las encimeras.'::text,'había limpiado'::text,'ha limpiado'::text,'limpia'::text,'Para cuando la cámara recorrió la cocina, ella ya había limpiado todas las encimeras.'::text),
(403322,44814,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la caméra a balayé la cuisine, elle ... déjà chaque plan de travail.'::text,'avait essuyé'::text,'a essuyé'::text,'essuie'::text,'Quand la caméra a balayé la cuisine, elle avait essuyé déjà chaque plan de travail.'::text),
(403325,44814,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera mutfağı taradığında o, bütün tezgâhları çoktan tertemiz ...'::text,'silmişti'::text,'sildi'::text,'siler'::text,'Kamera mutfağı taradığında o, bütün tezgâhları çoktan tertemiz silmişti.'::text),
(403326,44814,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kamera végigpásztázta a konyhát, ő már minden munkapultot tisztára ...'::text,'törölt'::text,'törölt'::text,'töröl'::text,'Mire a kamera végigpásztázta a konyhát, ő már minden munkapultot tisztára törölt.'::text),
(403329,44815,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie nach dem Frühstück wieder dieselbe Arbeitsplatte ab.'::text,'wischt gerade'::text,'wischt'::text,'wischt'::text,'Morgen um diese Zeit wischt gerade sie nach dem Frühstück wieder dieselbe Arbeitsplatte ab.'::text),
(403333,44815,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона ... ту саму стільницю знову після сніданку.'::text,'витиратиме'::text,'витре'::text,'витирає'::text,'Завтра в цей час вона витиратиме ту саму стільницю знову після сніданку.'::text),
(403332,44815,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, ... otra vez la misma encimera después del desayuno.'::text,'estará limpiando'::text,'limpiará'::text,'limpia'::text,'Mañana a esta hora, estará limpiando otra vez la misma encimera después del desayuno.'::text),
(403331,44815,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... encore le même plan de travail après le petit-déjeuner.'::text,'sera en train d''essuyer'::text,'essuiera'::text,'essuie'::text,'Demain à la même heure, elle sera en train d''essuyer encore le même plan de travail après le petit-déjeuner.'::text),
(403334,44815,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde kahvaltıdan sonra aynı tezgâhı yine ...'::text,'siliyor olacak'::text,'silecek'::text,'siler'::text,'Yarın bu saatlerde kahvaltıdan sonra aynı tezgâhı yine siliyor olacak.'::text),
(403335,44815,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor reggeli után újra ... ugyanazt a munkapultot.'::text,'törölni fogja'::text,'letörli'::text,'törli'::text,'Holnap ilyenkor reggeli után újra törölni fogja ugyanazt a munkapultot.'::text),
(403338,44816,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schaut auf den Herd und beschließt, dass sie ihn noch einmal ...'::text,'abwischen wird'::text,'abwischen wird'::text,'abwischt'::text,'Sie schaut auf den Herd und beschließt, dass sie ihn noch einmal abwischen wird.'::text),
(403342,44816,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона дивиться на плиту і вирішує, що ... її ще раз.'::text,'витре'::text,'витиратиме'::text,'витирає'::text,'Вона дивиться на плиту і вирішує, що витре її ще раз.'::text),
(403341,44816,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mira la vitro y decide que la ... una vez más.'::text,'limpiará'::text,'estará limpiando'::text,'está limpiando'::text,'Mira la vitro y decide que la limpiará una vez más.'::text),
(403340,44816,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle regarde la plaque et décide qu''elle ... encore une fois.'::text,'l''essuiera'::text,'sera en train de l''essuyer'::text,'l''essuie'::text,'Elle regarde la plaque et décide qu''elle l''essuiera encore une fois.'::text),
(403343,44816,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ocağa bakıyor ve onu bir kez daha ... karar veriyor.'::text,'sileceğine'::text,'sileceğine'::text,'sildiğine'::text,'Ocağa bakıyor ve onu bir kez daha sileceğine karar veriyor.'::text),
(403344,44816,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ránéz a tűzhelyre, és úgy dönt, hogy még egyszer ...'::text,'letörli'::text,'törölni fogja'::text,'törli'::text,'Ránéz a tűzhelyre, és úgy dönt, hogy még egyszer letörli.'::text),
(403347,44817,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn du eine Arbeitsplatte kreisförmig abwischst, ... sie viel sauberer, ehrlich.'::text,'wird'::text,'wird'::text,'wurde'::text,'Bro, wenn du eine Arbeitsplatte kreisförmig abwischst, wird sie viel sauberer, ehrlich.'::text),
(403351,44817,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо витирати стільницю по колу, вона ... набагато чистішою, без жартів.'::text,'стає'::text,'стане'::text,'стала'::text,'Бро, якщо витирати стільницю по колу, вона стає набагато чистішою, без жартів.'::text),
(403350,44817,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si limpias una encimera en círculos, ... mucho más limpia, en serio.'::text,'queda'::text,'quedará'::text,'quedó'::text,'Bro, si limpias una encimera en círculos, queda mucho más limpia, en serio.'::text),
(403349,44817,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si tu essuies un plan de travail en cercles, il ... bien plus propre, sans mentir.'::text,'devient'::text,'deviendra'::text,'est devenu'::text,'Frérot, si tu essuies un plan de travail en cercles, il devient bien plus propre, sans mentir.'::text),
(403352,44817,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tezgâhı daire çizerek silersen çok daha temiz ..., yalan yok.'::text,'olur'::text,'olacak'::text,'oldu'::text,'Kanka, tezgâhı daire çizerek silersen çok daha temiz olur, yalan yok.'::text),
(403353,44817,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha körkörösen törlöd a munkapultot, sokkal tisztább ..., komolyan.'::text,'lesz'::text,'lesz'::text,'lett'::text,'Tesó, ha körkörösen törlöd a munkapultot, sokkal tisztább lesz, komolyan.'::text),
(403356,44818,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, die hört nicht auf ..., bis die Küche blitzblank ist.'::text,'zu wischen'::text,'zu wischen'::text,'wischen'::text,'Nee, die hört nicht auf zu wischen, bis die Küche blitzblank ist.'::text),
(403360,44818,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не-а, вона не перестане ..., поки кухня не блищатиме.'::text,'витирати'::text,'витирати'::text,'витирати'::text,'Не-а, вона не перестане витирати, поки кухня не блищатиме.'::text),
(403359,44818,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, no va a dejar de ... hasta que la cocina esté impecable.'::text,'limpiar'::text,'limpiar'::text,'limpiar'::text,'Qué va, no va a dejar de limpiar hasta que la cocina esté impecable.'::text),
(403358,44818,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, elle va pas arrêter de ... tant que la cuisine sera pas nickel.'::text,'frotter'::text,'frotter'::text,'frotter'::text,'Nan, elle va pas arrêter de frotter tant que la cuisine sera pas nickel.'::text),
(403361,44818,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, bu mutfak pırıl pırıl olana kadar ... bırakmayacak.'::text,'silmeyi'::text,'silmeyi'::text,'silmek'::text,'Yok, bu mutfak pırıl pırıl olana kadar silmeyi bırakmayacak.'::text),
(403362,44818,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, nem fogja abbahagyni a ..., amíg ez a konyha nem lesz makulátlan.'::text,'törölgetést'::text,'törölgetést'::text,'törölgetést'::text,'Á, nem fogja abbahagyni a törölgetést, amíg ez a konyha nem lesz makulátlan.'::text),
(403365,44819,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Update: Sie ... gerade die letzte Arbeitsplatte, 2 Stunden vor der Deadline.'::text,'putzt'::text,'putzt'::text,'hat geputzt'::text,'Update: Sie putzt gerade die letzte Arbeitsplatte, 2 Stunden vor der Deadline.'::text),
(403369,44819,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оновлення: вона прямо зараз ... останню стільницю, на 2 години раніше дедлайну.'::text,'витирає'::text,'витирає'::text,'витерла'::text,'Оновлення: вона прямо зараз витирає останню стільницю, на 2 години раніше дедлайну.'::text),
(403368,44819,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualización: ahora mismo ... la última encimera, 2 horas antes del plazo.'::text,'está limpiando'::text,'limpia'::text,'ha limpiado'::text,'Actualización: ahora mismo está limpiando la última encimera, 2 horas antes del plazo.'::text),
(403367,44819,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mise à jour : elle ... le dernier plan de travail en ce moment, 2 heures avant l''échéance.'::text,'essuie'::text,'essuie'::text,'a essuyé'::text,'Mise à jour : elle essuie le dernier plan de travail en ce moment, 2 heures avant l''échéance.'::text),
(403370,44819,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güncelleme: şu anda son tezgâhı ..., teslim tarihinden 2 saat önce.'::text,'siliyor'::text,'siler'::text,'sildi'::text,'Güncelleme: şu anda son tezgâhı siliyor, teslim tarihinden 2 saat önce.'::text),
(403371,44819,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frissítés: épp most ... az utolsó munkapultot, 2 órával a határidő előtt.'::text,'törli'::text,'törli'::text,'törölte'::text,'Frissítés: épp most törli az utolsó munkapultot, 2 órával a határidő előtt.'::text),
(339960,37774,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit zwanzig Minuten alte Farbsplitter vom Holz.'::text,'schabt'::text,'schabt gerade'::text,'schabt'::text,'Er schabt seit zwanzig Minuten alte Farbsplitter vom Holz.'::text),
(339964,37774,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... шматочки старої фарби з дерева вже двадцять хвилин.'::text,'зіскрібає'::text,'зіскрібає'::text,'зіскрібає'::text,'Він зіскрібає шматочки старої фарби з дерева вже двадцять хвилин.'::text),
(339963,37774,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... trozos de pintura vieja de la madera desde hace veinte minutos.'::text,'Ha estado raspando'::text,'Está raspando'::text,'Raspa'::text,'Ha estado raspando trozos de pintura vieja de la madera desde hace veinte minutos.'::text),
(339962,37774,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des éclats de vieille peinture du bois depuis vingt minutes.'::text,'gratte'::text,'gratte'::text,'gratte'::text,'Il gratte des éclats de vieille peinture du bois depuis vingt minutes.'::text),
(339965,37774,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yirmi dakikadır tahtadan eski boya parçalarını ...'::text,'kazıyor'::text,'kazıyor'::text,'kazır'::text,'Yirmi dakikadır tahtadan eski boya parçalarını kazıyor.'::text),
(339966,37774,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Húsz perce ... a régi festék darabkáit a fáról.'::text,'kaparja le'::text,'kaparja le'::text,'kaparja le'::text,'Húsz perce kaparja le a régi festék darabkáit a fáról.'::text),
(339969,37775,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er kratzte, ... ein großer Farbsplitter auf den Boden.'::text,'fiel'::text,'fiel gerade'::text,'ist gefallen'::text,'Während er kratzte, fiel ein großer Farbsplitter auf den Boden.'::text),
(339973,37775,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він шкрябав, великий шматок фарби ... на підлогу.'::text,'упав'::text,'падав'::text,'упав'::text,'Поки він шкрябав, великий шматок фарби упав на підлогу.'::text),
(339972,37775,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras raspaba, un trozo grande de pintura ... al suelo.'::text,'cayó'::text,'estaba cayendo'::text,'ha caído'::text,'Mientras raspaba, un trozo grande de pintura cayó al suelo.'::text),
(339971,37775,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il grattait, un gros éclat de peinture ... par terre.'::text,'est tombé'::text,'tombait'::text,'est tombé'::text,'Pendant qu''il grattait, un gros éclat de peinture est tombé par terre.'::text),
(339974,37775,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kazırken büyük bir boya parçası yere ...'::text,'düştü'::text,'düşüyordu'::text,'düştü'::text,'O kazırken büyük bir boya parçası yere düştü.'::text),
(339975,37775,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben kapart, egy nagy festékdarab a földre ...'::text,'esett'::text,'hullott'::text,'leesett'::text,'Miközben kapart, egy nagy festékdarab a földre esett.'::text),
(339978,37776,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisher ... er Hunderte Farbsplitter vom Holz gekratzt.'::text,'hat'::text,'hat'::text,'kratzt'::text,'Bisher hat er Hunderte Farbsplitter vom Holz gekratzt.'::text),
(339982,37776,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досі він ... з дерева сотні шматочків фарби.'::text,'зіскріб'::text,'зіскрібав'::text,'зіскрібає'::text,'Досі він зіскріб з дерева сотні шматочків фарби.'::text),
(339981,37776,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora, ... cientos de trozos de pintura de la madera.'::text,'ha raspado'::text,'ha estado raspando'::text,'raspa'::text,'Hasta ahora, ha raspado cientos de trozos de pintura de la madera.'::text),
(339980,37776,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, il ... des centaines d''éclats de peinture du bois.'::text,'a gratté'::text,'gratte'::text,'gratte'::text,'Jusqu''ici, il a gratté des centaines d''éclats de peinture du bois.'::text),
(339983,37776,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar tahtadan yüzlerce boya parçası ...'::text,'kazıdı'::text,'kazıyor'::text,'kazır'::text,'Şimdiye kadar tahtadan yüzlerce boya parçası kazıdı.'::text),
(339984,37776,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig több száz festékdarabkát ... le a fáról.'::text,'kapart'::text,'kapart'::text,'kapar'::text,'Eddig több száz festékdarabkát kapart le a fáról.'::text),
(339987,37777,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Splitter fielen herunter, weil sie sich vom Holz ..., also waren sie nicht auf dem Holz.'::text,'gelöst hatten'::text,'gelöst haben'::text,'lösen'::text,'Die Splitter fielen herunter, weil sie sich vom Holz gelöst hatten, also waren sie nicht auf dem Holz.'::text),
(339991,37777,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Шматочки впали, бо вони ... від дерева, тож їх не було на дереві.'::text,'відокремилися'::text,'відокремилися'::text,'відокремлюються'::text,'Шматочки впали, бо вони відокремилися від дерева, тож їх не було на дереві.'::text),
(339990,37777,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los trozos cayeron porque ... de la madera, así que no estaban en la madera.'::text,'se habían desprendido'::text,'se han desprendido'::text,'se desprenden'::text,'Los trozos cayeron porque se habían desprendido de la madera, así que no estaban en la madera.'::text),
(339989,37777,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les éclats sont tombés parce qu''ils ... du bois, donc ils n''étaient pas sur le bois.'::text,'s''étaient détachés'::text,'se sont détachés'::text,'se détachent'::text,'Les éclats sont tombés parce qu''ils s''étaient détachés du bois, donc ils n''étaient pas sur le bois.'::text),
(339992,37777,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parçalar tahtadan ... düştü, yani tahtanın üstünde değillerdi.'::text,'ayrılmış oldukları için'::text,'ayrıldıkları için'::text,'ayrıldıkları için'::text,'Parçalar tahtadan ayrılmış oldukları için düştü, yani tahtanın üstünde değillerdi.'::text),
(339993,37777,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A darabkák leestek, mert ... a fáról, tehát nem voltak a fán.'::text,'leváltak'::text,'leváltak'::text,'leválnak'::text,'A darabkák leestek, mert leváltak a fáról, tehát nem voltak a fán.'::text),
(339996,37778,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er mehr Farbe abkratzt, ... mehr Splitter ab, weil Kratzen Splitter macht.'::text,'fallen'::text,'fielen'::text,'fielen'::text,'Wenn er mehr Farbe abkratzt, fallen mehr Splitter ab, weil Kratzen Splitter macht.'::text),
(340000,37778,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він зішкребе більше фарби, більше шматочків ..., бо шкрябання робить шматочки.'::text,'відпаде'::text,'відпало б'::text,'відпало'::text,'Якщо він зішкребе більше фарби, більше шматочків відпаде, бо шкрябання робить шматочки.'::text),
(339999,37778,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si raspa más pintura, ... más trozos, porque raspar hace trozos.'::text,'caerán'::text,'caerían'::text,'cayeron'::text,'Si raspa más pintura, caerán más trozos, porque raspar hace trozos.'::text),
(339998,37778,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il gratte plus de peinture, plus d''éclats ..., parce que gratter fait des éclats.'::text,'tomberont'::text,'tomberaient'::text,'sont tombés'::text,'S''il gratte plus de peinture, plus d''éclats tomberont, parce que gratter fait des éclats.'::text),
(340001,37778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha fazla boya kazırsa daha fazla parça ..., çünkü kazımak parça yapar.'::text,'düşecek'::text,'düşerdi'::text,'düştü'::text,'Daha fazla boya kazırsa daha fazla parça düşecek, çünkü kazımak parça yapar.'::text),
(340002,37778,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha több festéket kapar le, több darabka ..., mert a kaparás darabkákat csinál.'::text,'esik le'::text,'esne le'::text,'esett le'::text,'Ha több festéket kapar le, több darabka esik le, mert a kaparás darabkákat csinál.'::text),
(340005,37779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn noch ein Splitter abfiele, ... dieses alte Holz völlig kahl!'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn noch ein Splitter abfiele, wäre dieses alte Holz völlig kahl!'::text),
(340009,37779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби відпав ще один шматочок, це старе дерево ... зовсім голим!'::text,'було б'::text,'буде'::text,'є'::text,'Якби відпав ще один шматочок, це старе дерево було б зовсім голим!'::text),
(340008,37779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si cayera un trozo más, esta madera vieja ... completamente desnuda!'::text,'quedaría'::text,'quedará'::text,'queda'::text,'¡Si cayera un trozo más, esta madera vieja quedaría completamente desnuda!'::text),
(340007,37779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un éclat de plus tombait, ce vieux bois ... complètement nu !'::text,'serait'::text,'sera'::text,'est'::text,'Si un éclat de plus tombait, ce vieux bois serait complètement nu !'::text),
(340010,37779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir parça daha düşse bu eski tahta tamamen çıplak ...!'::text,'kalırdı'::text,'kalacak'::text,'kalır'::text,'Bir parça daha düşse bu eski tahta tamamen çıplak kalırdı!'::text),
(340011,37779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy darabka leesne, ez a régi fa teljesen csupasz ...!'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha még egy darabka leesne, ez a régi fa teljesen csupasz lenne!'::text),
(340014,37780,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeder einzelne Splitter ... von diesem gnadenlosen Schaber vom Holz geschoben!'::text,'wird'::text,'schiebt'::text,'hat'::text,'Jeder einzelne Splitter wird von diesem gnadenlosen Schaber vom Holz geschoben!'::text),
(340018,37780,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожен шматочок ... з дерева тим безжальним шкребком!'::text,'зіштовхується'::text,'штовхає'::text,'зіштовхнув'::text,'Кожен шматочок зіштовхується з дерева тим безжальним шкребком!'::text),
(340017,37780,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada trocito ... de la madera por esa rasqueta despiadada!'::text,'es arrancado'::text,'arranca'::text,'ha arrancado'::text,'¡Cada trocito es arrancado de la madera por esa rasqueta despiadada!'::text),
(340016,37780,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque éclat ... du bois par ce grattoir impitoyable !'::text,'est arraché'::text,'arrache'::text,'a arraché'::text,'Chaque éclat est arraché du bois par ce grattoir impitoyable !'::text),
(340019,37780,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her bir parça o acımasız kazıyıcı tarafından tahtadan ...!'::text,'itiliyor'::text,'itiyor'::text,'itti'::text,'Her bir parça o acımasız kazıyıcı tarafından tahtadan itiliyor!'::text),
(340020,37780,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden egyes darabkát az a könyörtelen kaparó ... le a fáról!'::text,'tolja'::text,'tolja'::text,'tolta'::text,'Minden egyes darabkát az a könyörtelen kaparó tolja le a fáról!'::text),
(340023,37781,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, dass er jeden Splitter mit einem einzigen Schaber ...'::text,'runtergeschoben hat'::text,'runtergeschoben wurde'::text,'runterschiebend'::text,'Hör zu, er hat mir erzählt, dass er jeden Splitter mit einem einzigen Schaber runtergeschoben hat.'::text),
(340027,37781,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що ... кожен шматочок одним шкребком.'::text,'зіштовхнув'::text,'був зіштовхнутий'::text,'зіштовхування'::text,'Слухай, він сказав мені, що зіштовхнув кожен шматочок одним шкребком.'::text),
(340026,37781,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que ... cada trozo con una sola rasqueta.'::text,'quitó'::text,'fue quitado'::text,'quitando'::text,'Oye, me dijo que quitó cada trozo con una sola rasqueta.'::text),
(340025,37781,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il ... chaque éclat avec un seul grattoir.'::text,'avait enlevé'::text,'avait été enlevé'::text,'enlevant'::text,'Écoute, il m''a dit qu''il avait enlevé chaque éclat avec un seul grattoir.'::text),
(340028,37781,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana her parçayı tek bir kazıyıcıyla ... söyledi.'::text,'ittiğini'::text,'itildiğini'::text,'itme'::text,'Dinle, bana her parçayı tek bir kazıyıcıyla ittiğini söyledi.'::text),
(340029,37781,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy egyetlen kaparóval ... le minden darabkát.'::text,'tolta'::text,'lett tolva'::text,'tolás'::text,'Figyelj, azt mondta, hogy egyetlen kaparóval tolta le minden darabkát.'::text),
(340032,37782,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Farbe ... Jahrzehnte alt sein, nach den Splittern zu urteilen. Ein makelloses Finish.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Diese Farbe muss Jahrzehnte alt sein, nach den Splittern zu urteilen. Ein makelloses Finish.'::text),
(340036,37782,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цій фарбі ... бути кілька десятиліть, судячи зі шматочків. Бездоганне покриття.'::text,'має'::text,'не може'::text,'мало б'::text,'Цій фарбі має бути кілька десятиліть, судячи зі шматочків. Бездоганне покриття.'::text),
(340035,37782,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta pintura ... tener décadas, a juzgar por los trozos. Un acabado impecable.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Esta pintura debe de tener décadas, a juzgar por los trozos. Un acabado impecable.'::text),
(340034,37782,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette peinture ... avoir des décennies, vu les éclats. Une finition impeccable.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Cette peinture doit avoir des décennies, vu les éclats. Une finition impeccable.'::text),
(340037,37782,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu boya onlarca yıllık ..., parçalara bakılırsa. Kusursuz bir yüzey.'::text,'olmalı'::text,'olamaz'::text,'olması lazım'::text,'Bu boya onlarca yıllık olmalı, parçalara bakılırsa. Kusursuz bir yüzey.'::text),
(340038,37782,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a festék ... évtizedes, a darabkákból ítélve. Hibátlan felület.'::text,'biztos'::text,'nem lehet'::text,'elvileg'::text,'Ez a festék biztos évtizedes, a darabkákból ítélve. Hibátlan felület.'::text),
(340041,37783,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, der Schaber, ... die Splitter runterschiebt, ist lowkey befriedigend, echt.'::text,'der'::text,'wer'::text,'dessen'::text,'Ey, der Schaber, der die Splitter runterschiebt, ist lowkey befriedigend, echt.'::text),
(340045,37783,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, шкребок, ... зіштовхує ці шматочки, лоукі кайфовий, чесно.'::text,'який'::text,'хто'::text,'чий'::text,'Йо, шкребок, який зіштовхує ці шматочки, лоукі кайфовий, чесно.'::text),
(340044,37783,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, la rasqueta ... quita esos trozos da una satisfacción que flipas, en serio.'::text,'que'::text,'quien'::text,'cuya'::text,'Oye, la rasqueta que quita esos trozos da una satisfacción que flipas, en serio.'::text),
(340043,37783,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, le grattoir ... enlève ces éclats est grave satisfaisant, sérieux.'::text,'qui'::text,'qui'::text,'dont'::text,'Yo, le grattoir qui enlève ces éclats est grave satisfaisant, sérieux.'::text),
(340046,37783,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, o parçaları ... kazıyıcı baya tatmin edici, cidden.'::text,'iten'::text,'iten'::text,'itenin'::text,'Yo, o parçaları iten kazıyıcı baya tatmin edici, cidden.'::text),
(340047,37783,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jó, az a kaparó, ... letolja azokat a darabkákat, lowkey kielégítő, komolyan.'::text,'amelyik'::text,'aki'::text,'akinek'::text,'Jó, az a kaparó, amelyik letolja azokat a darabkákat, lowkey kielégítő, komolyan.'::text),
(360426,40048,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht gelogen, du ... schon fünf saubere Treffer in Folge gemacht.'::text,'hast'::text,'hast'::text,'machst'::text,'Nicht gelogen, du hast schon fünf saubere Treffer in Folge gemacht.'::text),
(360430,40048,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти вже ... п''ять чистих ударів поспіль.'::text,'зробив'::text,'робив'::text,'робиш'::text,'Не буду брехати, ти вже зробив п''ять чистих ударів поспіль.'::text),
(360429,40048,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ya ... cinco golpes limpios seguidos.'::text,'has dado'::text,'has estado dando'::text,'estás dando'::text,'No voy a mentir, ya has dado cinco golpes limpios seguidos.'::text),
(360428,40048,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... déjà cinq frappes nettes d''affilée.'::text,'as fait'::text,'as fait'::text,'fais'::text,'Je vais pas mentir, tu as fait déjà cinq frappes nettes d''affilée.'::text),
(360431,40048,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, şimdiden art arda beş temiz vuruş ...'::text,'yaptın'::text,'yapıyorsun'::text,'yapıyorsun'::text,'Yalan yok, şimdiden art arda beş temiz vuruş yaptın.'::text),
(360432,40048,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, már öt tiszta ütést ... egymás után.'::text,'csináltál'::text,'csinálsz'::text,'csinálsz'::text,'Nem hazudok, már öt tiszta ütést csináltál egymás után.'::text),
(360435,40049,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als dein Schlag auf dem Rasen landete, ... du den Schläger schon gesenkt, so smooth.'::text,'hattest'::text,'hast'::text,'senkst'::text,'Als dein Schlag auf dem Rasen landete, hattest du den Schläger schon gesenkt, so smooth.'::text),
(360439,40049,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки твій удар приземлився на газон, ти вже ... биту, так плавно.'::text,'опустив'::text,'опустив'::text,'опускаєш'::text,'Поки твій удар приземлився на газон, ти вже опустив биту, так плавно.'::text),
(360438,40049,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando tu golpe cayó en el césped, ya ... el bate, qué estilo.'::text,'habías bajado'::text,'has bajado'::text,'bajas'::text,'Cuando tu golpe cayó en el césped, ya habías bajado el bate, qué estilo.'::text),
(360437,40049,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que ta frappe atterrisse sur la pelouse, tu ... déjà la batte, trop classe.'::text,'avais baissé'::text,'as baissé'::text,'baisses'::text,'Le temps que ta frappe atterrisse sur la pelouse, tu avais baissé déjà la batte, trop classe.'::text),
(360440,40049,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vuruşun çimlere düştüğünde sen sopayı çoktan ..., çok havalı.'::text,'indirmiştin'::text,'indirdin'::text,'indirirsin'::text,'Vuruşun çimlere düştüğünde sen sopayı çoktan indirmiştin, çok havalı.'::text),
(360441,40049,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az ütésed földet ért a gyepen, te már ... az ütőt, nagyon laza.'::text,'leengedted'::text,'leengedted'::text,'leengeded'::text,'Mire az ütésed földet ért a gyepen, te már leengedted az ütőt, nagyon laza.'::text),
(360444,40050,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein makelloser Schlag, ganz klar. Morgen um diese Zeit ... er Bälle aus dem Garten der Nachbarn.'::text,'sammelt gerade'::text,'sammelt'::text,'sammelt'::text,'Ein makelloser Schlag, ganz klar. Morgen um diese Zeit sammelt gerade er Bälle aus dem Garten der Nachbarn.'::text),
(360448,40050,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний удар, звісно. Завтра в цей час він ... м''ячі із саду сусідів.'::text,'збиратиме'::text,'збере'::text,'збирає'::text,'Бездоганний удар, звісно. Завтра в цей час він збиратиме м''ячі із саду сусідів.'::text),
(360447,40050,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un golpe impecable, claramente. Mañana a esta hora ... pelotas del jardín de los vecinos.'::text,'estará recogiendo'::text,'recogerá'::text,'recoge'::text,'Un golpe impecable, claramente. Mañana a esta hora estará recogiendo pelotas del jardín de los vecinos.'::text),
(360446,40050,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une frappe impeccable, clairement. Demain à la même heure, il ... des balles dans le jardin des voisins.'::text,'sera en train de ramasser'::text,'ramassera'::text,'ramasse'::text,'Une frappe impeccable, clairement. Demain à la même heure, il sera en train de ramasser des balles dans le jardin des voisins.'::text),
(360449,40050,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz bir vuruş, belli. Yarın bu saatlerde komşuların bahçesinden top ...'::text,'topluyor olacak'::text,'toplayacak'::text,'toplar'::text,'Kusursuz bir vuruş, belli. Yarın bu saatlerde komşuların bahçesinden top topluyor olacak.'::text),
(360450,40050,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan ütés, egyértelműen. Holnap ilyenkor ... a labdákat a szomszédok kertjéből.'::text,'szedi majd'::text,'összeszedi'::text,'szedi'::text,'Hibátlan ütés, egyértelműen. Holnap ilyenkor szedi majd a labdákat a szomszédok kertjéből.'::text),
(360453,40051,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er verspricht, dass er noch einen Schlag über den Zaun ..., na klar.'::text,'machen wird'::text,'machen wird'::text,'macht'::text,'Er verspricht, dass er noch einen Schlag über den Zaun machen wird, na klar.'::text),
(360457,40051,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обіцяє, що ... ще один удар через паркан, звісно.'::text,'зробить'::text,'робитиме'::text,'робить'::text,'Він обіцяє, що зробить ще один удар через паркан, звісно.'::text),
(360456,40051,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Promete que ... otro golpe por encima de la valla, obviamente.'::text,'dará'::text,'estará dando'::text,'está dando'::text,'Promete que dará otro golpe por encima de la valla, obviamente.'::text),
(360455,40051,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il promet qu''il ... une autre frappe par-dessus la clôture, évidemment.'::text,'fera'::text,'sera en train de faire'::text,'fait'::text,'Il promet qu''il fera une autre frappe par-dessus la clôture, évidemment.'::text),
(360458,40051,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çitin üzerinden bir vuruş daha ... söz veriyor, tabii ki.'::text,'yapacağına'::text,'yapacağına'::text,'yaptığına'::text,'Çitin üzerinden bir vuruş daha yapacağına söz veriyor, tabii ki.'::text),
(360459,40051,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígéri, hogy ... még egy ütést a kerítésen át, persze.'::text,'csinál'::text,'csinálni fog'::text,'csinál'::text,'Megígéri, hogy csinál még egy ütést a kerítésen át, persze.'::text),
(360462,40052,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Schlag den Ball über den Zaun ..., behalten ihn die Nachbarn. Super gemacht.'::text,'schickt'::text,'schickte'::text,'schicken wird'::text,'Wenn ein Schlag den Ball über den Zaun schickt, behalten ihn die Nachbarn. Super gemacht.'::text),
(360466,40052,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо удар ... м''яч через паркан, сусіди залишають його собі. Чудова робота.'::text,'відправляє'::text,'відправив'::text,'відправить'::text,'Якщо удар відправляє м''яч через паркан, сусіди залишають його собі. Чудова робота.'::text),
(360465,40052,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un golpe ... la pelota por encima de la valla, los vecinos se la quedan. Buen trabajo.'::text,'manda'::text,'mandó'::text,'mandará'::text,'Si un golpe manda la pelota por encima de la valla, los vecinos se la quedan. Buen trabajo.'::text),
(360464,40052,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une frappe ... la balle par-dessus la clôture, les voisins la gardent. Bravo.'::text,'envoie'::text,'a envoyé'::text,'enverra'::text,'Si une frappe envoie la balle par-dessus la clôture, les voisins la gardent. Bravo.'::text),
(360467,40052,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir vuruş topu çitin üzerinden ..., komşular onu alıkoyar. Harika iş.'::text,'gönderirse'::text,'gönderdiyse'::text,'gönderecekse'::text,'Bir vuruş topu çitin üzerinden gönderirse, komşular onu alıkoyar. Harika iş.'::text),
(360468,40052,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy ütés a kerítésen át ... a labdát, a szomszédok megtartják. Szép munka.'::text,'küldi'::text,'küldte'::text,'küldeni fogja'::text,'Ha egy ütés a kerítésen át küldi a labdát, a szomszédok megtartják. Szép munka.'::text),
(360471,40053,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sein nächster Schlag das Fenster des Nachbarn ..., wird es eine totale Katastrophe!'::text,'zerschlägt'::text,'zerschlagen wird'::text,'zerschlug'::text,'Wenn sein nächster Schlag das Fenster des Nachbarn zerschlägt, wird es eine totale Katastrophe!'::text),
(360475,40053,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо його наступний удар ... вікно сусіда, це буде повна катастрофа!'::text,'розіб''є'::text,'розіб''є'::text,'розбив'::text,'Якщо його наступний удар розіб''є вікно сусіда, це буде повна катастрофа!'::text),
(360474,40053,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si su próximo golpe ... la ventana del vecino, será un desastre total!'::text,'rompe'::text,'romperá'::text,'rompió'::text,'¡Si su próximo golpe rompe la ventana del vecino, será un desastre total!'::text),
(360473,40053,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si son prochain coup ... la fenêtre du voisin, ce sera une catastrophe totale !'::text,'casse'::text,'cassera'::text,'a cassé'::text,'Si son prochain coup casse la fenêtre du voisin, ce sera une catastrophe totale !'::text),
(360476,40053,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sonraki vuruşu komşunun camını ..., tam bir felaket olacak!'::text,'kırarsa'::text,'kıracak olursa'::text,'kırdıysa'::text,'Bir sonraki vuruşu komşunun camını kırarsa, tam bir felaket olacak!'::text),
(360477,40053,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a következő ütése ... a szomszéd ablakát, az teljes katasztrófa lesz!'::text,'betöri'::text,'be fogja törni'::text,'betörte'::text,'Ha a következő ütése betöri a szomszéd ablakát, az teljes katasztrófa lesz!'::text),
(360480,40054,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn dieser Schlag über den Zaun ginge, ... er den Ball für immer los!'::text,'wäre'::text,'ist'::text,'ist'::text,'Wenn dieser Schlag über den Zaun ginge, wäre er den Ball für immer los!'::text),
(360484,40054,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби той удар полетів через паркан, він ... м''яч назавжди!'::text,'втратив би'::text,'втратить'::text,'втрачає'::text,'Якби той удар полетів через паркан, він втратив би м''яч назавжди!'::text),
(360483,40054,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si ese golpe pasara la valla, ... la pelota para siempre!'::text,'perdería'::text,'perderá'::text,'pierde'::text,'¡Si ese golpe pasara la valla, perdería la pelota para siempre!'::text),
(360482,40054,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cette frappe passait par-dessus la clôture, il ... la balle pour toujours !'::text,'perdrait'::text,'perdra'::text,'perd'::text,'Si cette frappe passait par-dessus la clôture, il perdrait la balle pour toujours !'::text),
(360485,40054,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O vuruş çitin üzerinden geçse topu sonsuza dek ...!'::text,'kaybederdi'::text,'kaybedecek'::text,'kaybeder'::text,'O vuruş çitin üzerinden geçse topu sonsuza dek kaybederdi!'::text),
(360486,40054,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az az ütés átmenne a kerítésen, örökre ... a labdát!'::text,'elveszítené'::text,'elveszíti'::text,'elveszíti'::text,'Ha az az ütés átmenne a kerítésen, örökre elveszítené a labdát!'::text),
(360489,40055,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, sein großer Schlag ... anscheinend vom Nachbarn mit dem Handy gefilmt.'::text,'wurde'::text,'hat'::text,'wird'::text,'Also, sein großer Schlag wurde anscheinend vom Nachbarn mit dem Handy gefilmt.'::text),
(360493,40055,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, його крутий удар, кажуть, ... сусідом на телефон.'::text,'був знятий'::text,'зняв'::text,'знімається'::text,'Коротше, його крутий удар, кажуть, був знятий сусідом на телефон.'::text),
(360492,40055,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bueno, pues su gran golpe ... con el móvil por el vecino, al parecer.'::text,'fue grabado'::text,'grabó'::text,'es grabado'::text,'Bueno, pues su gran golpe fue grabado con el móvil por el vecino, al parecer.'::text),
(360491,40055,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, son gros coup ... au téléphone par le voisin, apparemment.'::text,'a été filmé'::text,'a filmé'::text,'est filmé'::text,'Bon alors, son gros coup a été filmé au téléphone par le voisin, apparemment.'::text),
(360494,40055,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yani, onun büyük vuruşu komşu tarafından telefonla ..., öyle diyorlar.'::text,'çekildi'::text,'çekti'::text,'çekiliyor'::text,'Yani, onun büyük vuruşu komşu tarafından telefonla çekildi, öyle diyorlar.'::text),
(360495,40055,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval a nagy ütése állítólag ... a szomszéd telefonjával.'::text,'le lett filmezve'::text,'lefilmezte'::text,'le van filmezve'::text,'Szóval a nagy ütése állítólag le lett filmezve a szomszéd telefonjával.'::text),
(360498,40056,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann ... den Ball mit einem sauberen Schlag hoch über den Rasen.'::text,'schickte'::text,'wurde geschickt'::text,'schickend'::text,'Der junge Mann schickte den Ball mit einem sauberen Schlag hoch über den Rasen.'::text),
(360502,40056,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий чоловік ... м''яч високо над газоном чистим ударом.'::text,'відправив'::text,'був відправлений'::text,'відправлення'::text,'Молодий чоловік відправив м''яч високо над газоном чистим ударом.'::text),
(360501,40056,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El joven ... la pelota muy alto sobre el césped con un golpe limpio.'::text,'mandó'::text,'fue mandado'::text,'mandando'::text,'El joven mandó la pelota muy alto sobre el césped con un golpe limpio.'::text),
(360500,40056,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme ... la balle haut au-dessus de la pelouse d''une frappe nette.'::text,'a envoyé'::text,'a été envoyé'::text,'envoyant'::text,'Le jeune homme a envoyé la balle haut au-dessus de la pelouse d''une frappe nette.'::text),
(360503,40056,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam temiz bir vuruşla topu çimlerin üzerinden yükseğe ...'::text,'gönderdi'::text,'gönderildi'::text,'gönderme'::text,'Genç adam temiz bir vuruşla topu çimlerin üzerinden yükseğe gönderdi.'::text),
(360504,40056,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatalember egy tiszta ütéssel magasra ... a labdát a gyep fölött.'::text,'küldte'::text,'lett küldve'::text,'küldés'::text,'A fiatalember egy tiszta ütéssel magasra küldte a labdát a gyep fölött.'::text),
(360507,40057,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach so einem hohen Schlag ... der Ball weit weg sein, aber keiner ist sich sicher.'::text,'könnte'::text,'muss'::text,'sollte'::text,'Nach so einem hohen Schlag könnte der Ball weit weg sein, aber keiner ist sich sicher.'::text),
(360511,40057,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після такого високого удару м''яч ... бути далеко, але ніхто не впевнений.'::text,'може'::text,'має'::text,'мав би'::text,'Після такого високого удару м''яч може бути далеко, але ніхто не впевнений.'::text),
(360510,40057,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después de un golpe tan alto, la pelota ... estar lejos, pero nadie está seguro.'::text,'podría'::text,'debe de'::text,'debería'::text,'Después de un golpe tan alto, la pelota podría estar lejos, pero nadie está seguro.'::text),
(360509,40057,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après une frappe aussi haute, la balle ... être loin, mais personne n''est sûr.'::text,'pourrait'::text,'doit'::text,'devrait'::text,'Après une frappe aussi haute, la balle pourrait être loin, mais personne n''est sûr.'::text),
(360512,40057,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Böyle yüksek bir vuruştan sonra top uzakta ..., ama kimse emin değil.'::text,'olabilir'::text,'olmalı'::text,'olması gerek'::text,'Böyle yüksek bir vuruştan sonra top uzakta olabilir, ama kimse emin değil.'::text),
(360513,40057,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy ilyen magas ütés után a labda ... messze, de senki sem biztos benne.'::text,'lehet'::text,'biztos van'::text,'kéne legyen'::text,'Egy ilyen magas ütés után a labda lehet messze, de senki sem biztos benne.'::text),
(380919,42325,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du weiter diesen Grat entlanggehst, ... du den Gipfel vor dem Mittagessen.'::text,'erreichst'::text,'erreichtest'::text,'erreichtest'::text,'Ehrlich, wenn du weiter diesen Grat entlanggehst, erreichst du den Gipfel vor dem Mittagessen.'::text),
(380923,42325,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якщо ти й далі йтимеш цим хребтом, ти ... вершини до обіду.'::text,'досягнеш'::text,'досяг би'::text,'досяг'::text,'Чесно, якщо ти й далі йтимеш цим хребтом, ти досягнеш вершини до обіду.'::text),
(380922,42325,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, si sigues caminando por esta cresta, ... la cumbre antes de comer.'::text,'alcanzarás'::text,'alcanzarías'::text,'alcanzaste'::text,'La verdad, si sigues caminando por esta cresta, alcanzarás la cumbre antes de comer.'::text),
(380921,42325,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu continues à marcher sur cette crête, tu ... le sommet avant le déjeuner.'::text,'atteindras'::text,'atteindrais'::text,'as atteint'::text,'Franchement, si tu continues à marcher sur cette crête, tu atteindras le sommet avant le déjeuner.'::text),
(380924,42325,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bu sırt boyunca yürümeye devam edersen öğle yemeğinden önce zirveye ...'::text,'ulaşacaksın'::text,'ulaşırdın'::text,'ulaştın'::text,'Açıkçası bu sırt boyunca yürümeye devam edersen öğle yemeğinden önce zirveye ulaşacaksın.'::text),
(380925,42325,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha tovább mész ezen a gerincen, ebéd előtt ... a csúcsra.'::text,'felérsz'::text,'felérnél'::text,'felértél'::text,'Őszintén, ha tovább mész ezen a gerincen, ebéd előtt felérsz a csúcsra.'::text),
(380928,42326,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Grat noch schmaler wäre, ... er auf Luft laufen. Ein entspannter Spaziergang, klar.'::text,'müsste'::text,'muss'::text,'muss'::text,'Wenn der Grat noch schmaler wäre, müsste er auf Luft laufen. Ein entspannter Spaziergang, klar.'::text),
(380932,42326,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби хребет був ще вужчим, він ... ходити по повітрю. Розслаблена прогулянка, звісно.'::text,'мусив би'::text,'муситиме'::text,'мусить'::text,'Якби хребет був ще вужчим, він мусив би ходити по повітрю. Розслаблена прогулянка, звісно.'::text),
(380931,42326,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la cresta fuera más estrecha, ... caminar sobre el aire. Un paseo relajante, obviamente.'::text,'tendría que'::text,'tendrá que'::text,'tiene que'::text,'Si la cresta fuera más estrecha, tendría que caminar sobre el aire. Un paseo relajante, obviamente.'::text),
(380930,42326,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la crête était plus étroite, il ... marcher dans le vide. Une balade relaxante, évidemment.'::text,'devrait'::text,'devra'::text,'doit'::text,'Si la crête était plus étroite, il devrait marcher dans le vide. Une balade relaxante, évidemment.'::text),
(380933,42326,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırt biraz daha dar olsa havada yürümek ... – rahatlatıcı bir yürüyüş tabii.'::text,'zorunda kalırdı'::text,'zorunda kalacak'::text,'zorunda'::text,'Sırt biraz daha dar olsa havada yürümek zorunda kalırdı – rahatlatıcı bir yürüyüş tabii.'::text),
(380934,42326,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a gerinc még keskenyebb lenne, ... a levegőn járnia. Pihentető séta, persze.'::text,'kellene'::text,'kell majd'::text,'kell'::text,'Ha a gerinc még keskenyebb lenne, kellene a levegőn járnia. Pihentető séta, persze.'::text),
(380937,42327,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schnee auf dem Grat ... von früheren Bergsteigern platt getreten. Eine echte Autobahn, klar.'::text,'wurde'::text,'wird'::text,'trat'::text,'Der Schnee auf dem Grat wurde von früheren Bergsteigern platt getreten. Eine echte Autobahn, klar.'::text),
(380941,42327,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сніг на хребті ... попередніми альпіністами. Справжня автострада, звісно.'::text,'був утоптаний'::text,'утоптаний'::text,'утоптав'::text,'Сніг на хребті був утоптаний попередніми альпіністами. Справжня автострада, звісно.'::text),
(380940,42327,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La nieve de la cresta ... por escaladores anteriores hasta quedar lisa. Una auténtica autopista, obviamente.'::text,'fue pisoteada'::text,'es pisoteada'::text,'pisoteó'::text,'La nieve de la cresta fue pisoteada por escaladores anteriores hasta quedar lisa. Una auténtica autopista, obviamente.'::text),
(380939,42327,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La neige sur la crête ... par des grimpeurs précédents. Une vraie autoroute, évidemment.'::text,'a été tassée'::text,'est tassée'::text,'a tassé'::text,'La neige sur la crête a été tassée par des grimpeurs précédents. Une vraie autoroute, évidemment.'::text),
(380942,42327,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırttaki kar daha önceki dağcılar tarafından dümdüz ..., gerçek bir otoyol tabii.'::text,'çiğnendi'::text,'çiğnenir'::text,'çiğnedi'::text,'Sırttaki kar daha önceki dağcılar tarafından dümdüz çiğnendi, gerçek bir otoyol tabii.'::text),
(380943,42327,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gerincen a hó ... a korábbi hegymászóktól. Igazi autópálya, persze.'::text,'le lett taposva'::text,'le van taposva'::text,'letaposta'::text,'A gerincen a hó le lett taposva a korábbi hegymászóktól. Igazi autópálya, persze.'::text),
(380946,42328,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich am messerscharfen Grat entlang. Keine große Sache, nur Wolken auf beiden Seiten.'::text,'schiebt'::text,'wird geschoben'::text,'schiebend'::text,'Er schiebt sich am messerscharfen Grat entlang. Keine große Sache, nur Wolken auf beiden Seiten.'::text),
(380950,42328,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... хребтом, тонким як лезо. Нічого такого, просто хмари з обох боків.'::text,'просувається'::text,'його просувають'::text,'просування'::text,'Він просувається хребтом, тонким як лезо. Нічого такого, просто хмари з обох боків.'::text),
(380949,42328,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... poco a poco por la cresta afilada como un cuchillo. Nada del otro mundo, solo nubes a ambos lados.'::text,'Avanza'::text,'Es avanzado'::text,'Avanzando'::text,'Avanza poco a poco por la cresta afilada como un cuchillo. Nada del otro mundo, solo nubes a ambos lados.'::text),
(380948,42328,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le long de la crête fine comme une lame. Rien de grave, juste des nuages des deux côtés.'::text,'progresse'::text,'est progressé'::text,'progressant'::text,'Il progresse le long de la crête fine comme une lame. Rien de grave, juste des nuages des deux côtés.'::text),
(380951,42328,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bıçak gibi ince sırt boyunca yavaş yavaş ..., önemli bir şey değil, iki yanda sadece bulutlar var.'::text,'ilerliyor'::text,'ilerletiliyor'::text,'ilerleme'::text,'Bıçak gibi ince sırt boyunca yavaş yavaş ilerliyor, önemli bir şey değil, iki yanda sadece bulutlar var.'::text),
(380952,42328,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... végig a borotvaéles gerincen. Semmi extra, csak felhők mindkét oldalon.'::text,'araszol'::text,'araszoltatva van'::text,'araszolás'::text,'Ő araszol végig a borotvaéles gerincen. Semmi extra, csak felhők mindkét oldalon.'::text),
(380964,42330,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Grat, ... er läuft, ist erschreckend schmal!'::text,'auf dem'::text,'wer'::text,'wo'::text,'Der Grat, auf dem er läuft, ist erschreckend schmal!'::text),
(380968,42330,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хребет, ... він іде, жахливо тонкий!'::text,'яким'::text,'хто'::text,'де'::text,'Хребет, яким він іде, жахливо тонкий!'::text),
(380967,42330,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La cresta ... camina es terroríficamente estrecha!'::text,'por la que'::text,'quien'::text,'donde'::text,'¡La cresta por la que camina es terroríficamente estrecha!'::text),
(380966,42330,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La crête ... il marche est terriblement fine !'::text,'sur laquelle'::text,'qui'::text,'où'::text,'La crête sur laquelle il marche est terriblement fine !'::text),
(380969,42330,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... yürüdüğü sırt korkunç derecede ince!'::text,'Üzerinde'::text,'Kimin'::text,'Nerede'::text,'Üzerinde yürüdüğü sırt korkunç derecede ince!'::text),
(380970,42330,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gerinc, ... sétál, ijesztően vékony!'::text,'amelyen'::text,'aki'::text,'ahol'::text,'A gerinc, amelyen sétál, ijesztően vékony!'::text),
(380973,42331,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, dass er auf diesem Grat direkt über das Dach der Welt ...'::text,'gelaufen ist'::text,'läuft'::text,'gelaufen war'::text,'Mädel, er hat mir erzählt, dass er auf diesem Grat direkt über das Dach der Welt gelaufen ist.'::text),
(380977,42331,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що ... просто по даху світу на тому хребті.'::text,'йшов'::text,'іде'::text,'пройшов'::text,'Подруго, він сказав мені, що йшов просто по даху світу на тому хребті.'::text),
(380976,42331,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que ... justo por el techo del mundo en esa cresta.'::text,'caminó'::text,'camina'::text,'había caminado'::text,'Tía, me dijo que caminó justo por el techo del mundo en esa cresta.'::text),
(380975,42331,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il ... carrément sur le toit du monde sur cette crête.'::text,'a marché'::text,'marche'::text,'avait marché'::text,'Meuf, il m''a dit qu''il a marché carrément sur le toit du monde sur cette crête.'::text),
(380978,42331,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana o sırtta dünyanın tam tepesinde ... anlattı.'::text,'yürüdüğünü'::text,'yürüdüğünü'::text,'yürümüş olduğunu'::text,'Kızım, bana o sırtta dünyanın tam tepesinde yürüdüğünü anlattı.'::text),
(380979,42331,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy azon a gerincen egyenesen a világ tetején ...'::text,'sétált'::text,'sétál'::text,'sétált'::text,'Csajszi, azt mondta, hogy azon a gerincen egyenesen a világ tetején sétált.'::text),
(380982,42332,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er ... angeblich Höhenangst, bevor er auf Grate stieg.'::text,'hatte früher'::text,'hatte'::text,'war gewohnt'::text,'Hör zu, er hatte früher angeblich Höhenangst, bevor er auf Grate stieg.'::text),
(380986,42332,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він ... боявся висоти, поки не почав лазити по хребтах.'::text,'раніше'::text,'бувало'::text,'звик'::text,'Слухай, кажуть, він раніше боявся висоти, поки не почав лазити по хребтах.'::text),
(380985,42332,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ... tener miedo a las alturas antes de escalar crestas.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Oye, al parecer solía tener miedo a las alturas antes de escalar crestas.'::text),
(380984,42332,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il ... peur du vide avant de grimper des crêtes.'::text,'avait'::text,'avait'::text,'était habitué à avoir'::text,'Écoute, apparemment il avait peur du vide avant de grimper des crêtes.'::text),
(380987,42332,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya sırtlara tırmanmadan önce yükseklikten ...'::text,'korkardı'::text,'korkardı'::text,'korkmaya alışkındı'::text,'Dinle, güya sırtlara tırmanmadan önce yükseklikten korkardı.'::text),
(380988,42332,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ... tériszonya volt, mielőtt gerincekre mászott.'::text,'régen'::text,'annak idején'::text,'hozzá volt szokva'::text,'Figyelj, állítólag régen tériszonya volt, mielőtt gerincekre mászott.'::text),
(380991,42333,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... immer weiter den Grat entlang Richtung Gipfel.'::text,'geht'::text,'geht'::text,'geht'::text,'Er geht immer weiter den Grat entlang Richtung Gipfel.'::text),
(380995,42333,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він і далі ... хребтом до вершини.'::text,'іде'::text,'іде'::text,'іде'::text,'Він і далі іде хребтом до вершини.'::text),
(380994,42333,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sigue ... por la cresta hacia la cumbre.'::text,'caminando'::text,'caminar'::text,'caminar'::text,'Sigue caminando por la cresta hacia la cumbre.'::text),
(380993,42333,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il continue à ... le long de la crête vers le sommet.'::text,'marcher'::text,'marcher'::text,'marcher'::text,'Il continue à marcher le long de la crête vers le sommet.'::text),
(380996,42333,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırt boyunca zirveye doğru ... devam ediyor.'::text,'yürümeye'::text,'yürümeye'::text,'yürümek'::text,'Sırt boyunca zirveye doğru yürümeye devam ediyor.'::text),
(380997,42333,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tovább ... a gerincen a csúcs felé.'::text,'megy'::text,'megy'::text,'megy'::text,'Tovább megy a gerincen a csúcs felé.'::text),
(381000,42334,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Grat ist sehr schmal, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Der Grat ist sehr schmal, oder?'::text),
(381004,42334,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хребет дуже вузький, ...?'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Хребет дуже вузький, правда?'::text),
(381003,42334,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cresta es muy estrecha, ...?'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'La cresta es muy estrecha, ¿verdad?'::text),
(381002,42334,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La crête est très étroite, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'La crête est très étroite, non ?'::text),
(381005,42334,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırt çok dar, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil miydi?'::text,'Sırt çok dar, değil mi?'::text),
(381006,42334,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gerinc nagyon keskeny, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'A gerinc nagyon keskeny, ugye?'::text),
(381009,42335,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Grat ragt über die Wolken, und ...'::text,'der Gipfel auch.'::text,'der Gipfel auch.'::text,'der Gipfel auch.'::text,'Der Grat ragt über die Wolken, und der Gipfel auch.'::text),
(381013,42335,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хребет височіє над хмарами, і ...'::text,'вершина теж.'::text,'вершина теж.'::text,'вершина теж.'::text,'Хребет височіє над хмарами, і вершина теж.'::text),
(381012,42335,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cresta se eleva sobre las nubes, y ...'::text,'la cumbre también.'::text,'la cumbre también.'::text,'la cumbre también.'::text,'La cresta se eleva sobre las nubes, y la cumbre también.'::text),
(381011,42335,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La crête s''élève au-dessus des nuages, et ...'::text,'le sommet aussi.'::text,'le sommet aussi.'::text,'le sommet aussi.'::text,'La crête s''élève au-dessus des nuages, et le sommet aussi.'::text),
(381014,42335,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırt bulutların üzerinde yükseliyor, ...'::text,'zirve de öyle.'::text,'zirve de öyle.'::text,'zirve de öyle.'::text,'Sırt bulutların üzerinde yükseliyor, zirve de öyle.'::text),
(381015,42335,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gerinc a felhők fölé emelkedik, és ...'::text,'a csúcs is.'::text,'a csúcs is.'::text,'a csúcs is.'::text,'A gerinc a felhők fölé emelkedik, és a csúcs is.'::text),
(383331,42593,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... stundenlang an dem Stamm gesägt, bevor der Bär auftauchte, lowkey krank.'::text,'hatte'::text,'hat'::text,'sägte'::text,'Bro, er hatte stundenlang an dem Stamm gesägt, bevor der Bär auftauchte, lowkey krank.'::text),
(383335,42593,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... той стовбур годинами, перш ніж з''явився ведмідь, лоукі божевілля.'::text,'пиляв'::text,'пиляє'::text,'пиляв'::text,'Бро, він пиляв той стовбур годинами, перш ніж з''явився ведмідь, лоукі божевілля.'::text),
(383334,42593,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... horas serrando ese tronco antes de que apareciera el oso, una locura.'::text,'llevaba'::text,'lleva'::text,'estaba'::text,'Bro, llevaba horas serrando ese tronco antes de que apareciera el oso, una locura.'::text),
(383333,42593,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... ce tronc depuis des heures quand l''ours est apparu, grave dingue.'::text,'sciait'::text,'scie'::text,'sciait'::text,'Frérot, il sciait ce tronc depuis des heures quand l''ours est apparu, grave dingue.'::text),
(383336,42593,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ayı ortaya çıkana kadar o gövdeyi saatlerce ..., resmen delilik.'::text,'kesiyordu'::text,'kesiyor'::text,'kesiyordu'::text,'Kanka, ayı ortaya çıkana kadar o gövdeyi saatlerce kesiyordu, resmen delilik.'::text),
(383337,42593,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, órákig ... azt a törzset, mielőtt előbukkant a medve, lowkey őrület.'::text,'fűrészelte'::text,'fűrészeli'::text,'fűrészelte'::text,'Tesó, órákig fűrészelte azt a törzset, mielőtt előbukkant a medve, lowkey őrület.'::text),
(383340,42594,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, bis heute Abend ... er den ganzen Bären aus dem Stamm rausgesägt, kein Witz.'::text,'hat'::text,'sägt'::text,'sägt gerade'::text,'Alter, bis heute Abend hat er den ganzen Bären aus dem Stamm rausgesägt, kein Witz.'::text),
(383344,42594,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, до вечора він ... всього ведмедя з того стовбура, без жартів.'::text,'випиляє'::text,'випиляє'::text,'пилятиме'::text,'Чувак, до вечора він випиляє всього ведмедя з того стовбура, без жартів.'::text),
(383343,42594,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, para esta noche ... el oso entero de ese tronco, en serio.'::text,'habrá serrado'::text,'serrará'::text,'estará serrando'::text,'Tío, para esta noche habrá serrado el oso entero de ese tronco, en serio.'::text),
(383342,42594,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, d''ici ce soir, il ... tout l''ours dans ce tronc, sans mentir.'::text,'aura scié'::text,'sciera'::text,'sera en train de scier'::text,'Mec, d''ici ce soir, il aura scié tout l''ours dans ce tronc, sans mentir.'::text),
(383345,42594,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu akşama kadar bütün ayıyı o gövdeden ..., yalan yok.'::text,'kesip çıkarmış olacak'::text,'kesip çıkaracak'::text,'kesiyor olacak'::text,'Kanka, bu akşama kadar bütün ayıyı o gövdeden kesip çıkarmış olacak, yalan yok.'::text),
(383346,42594,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ma estére ... az egész medvét abból a törzsből, komolyan.'::text,'kifűrészeli'::text,'kifűrészeli'::text,'fűrészelni fogja'::text,'Tesó, ma estére kifűrészeli az egész medvét abból a törzsből, komolyan.'::text),
(383349,42595,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum nächsten Vertrag ... er seit 3 Jahren Bären aus Stämmen.'::text,'sägt'::text,'sägt'::text,'sägt'::text,'Bis zum nächsten Vertrag sägt er seit 3 Jahren Bären aus Stämmen.'::text),
(383353,42595,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наступного контракту він ... ведмедів зі стовбурів уже 3 роки.'::text,'пилятиме'::text,'пилятиме'::text,'пиляє'::text,'До наступного контракту він пилятиме ведмедів зі стовбурів уже 3 роки.'::text),
(383352,42595,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el próximo contrato, ... 3 años serrando osos de troncos.'::text,'llevará'::text,'estará'::text,'lleva'::text,'Para el próximo contrato, llevará 3 años serrando osos de troncos.'::text),
(383351,42595,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le prochain contrat, il ... des ours dans des troncs depuis 3 ans.'::text,'sciera'::text,'sciera'::text,'scie'::text,'D''ici le prochain contrat, il sciera des ours dans des troncs depuis 3 ans.'::text),
(383354,42595,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sonraki sözleşmeye kadar 3 yıldır gövdelerden ayı ...'::text,'kesiyor olacak'::text,'kesiyor olacak'::text,'kesiyor'::text,'Bir sonraki sözleşmeye kadar 3 yıldır gövdelerden ayı kesiyor olacak.'::text),
(383355,42595,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A következő szerződésig már 3 éve ... medvéket törzsekből.'::text,'fog fűrészelni'::text,'fog fűrészelni'::text,'fűrészel'::text,'A következő szerződésig már 3 éve fog fűrészelni medvéket törzsekből.'::text),
(383358,42596,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er nicht so vorsichtig gesägt hätte, ... der Bär seine Beine verloren.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn er nicht so vorsichtig gesägt hätte, hätte der Bär seine Beine verloren.'::text),
(383362,42596,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не пиляв так обережно, ведмідь ... лап.'::text,'позбувся б'::text,'позбудеться'::text,'позбувся'::text,'Якби він не пиляв так обережно, ведмідь позбувся б лап.'::text),
(383361,42596,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera serrado con tanto cuidado, el oso ... las patas.'::text,'habría perdido'::text,'perderá'::text,'perdió'::text,'Si no hubiera serrado con tanto cuidado, el oso habría perdido las patas.'::text),
(383360,42596,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas scié aussi prudemment, l''ours ... ses pattes.'::text,'aurait perdu'::text,'perdra'::text,'a perdu'::text,'S''il n''avait pas scié aussi prudemment, l''ours aurait perdu ses pattes.'::text),
(383363,42596,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kadar dikkatli kesmeseydi, ayı bacaklarını ...'::text,'kaybetmiş olurdu'::text,'kaybedecek'::text,'kaybetti'::text,'O kadar dikkatli kesmeseydi, ayı bacaklarını kaybetmiş olurdu.'::text),
(383364,42596,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem fűrészelt volna ilyen óvatosan, a medve ... a lábait.'::text,'elvesztette volna'::text,'elveszíti'::text,'elvesztette'::text,'Ha nem fűrészelt volna ilyen óvatosan, a medve elvesztette volna a lábait.'::text),
(383376,42598,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bär soll nur mit einer Kettensäge aus einem einzigen Stamm ...'::text,'gesägt worden sein'::text,'sägen'::text,'sägend'::text,'Der Bär soll nur mit einer Kettensäge aus einem einzigen Stamm gesägt worden sein.'::text),
(383380,42598,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що ведмедя ... з одного стовбура лише бензопилою.'::text,'випиляли'::text,'пиляти'::text,'пиляння'::text,'Кажуть, що ведмедя випиляли з одного стовбура лише бензопилою.'::text),
(383379,42598,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que el oso ... de un solo tronco solo con una motosierra.'::text,'fue serrado'::text,'serrar'::text,'serrando'::text,'Se dice que el oso fue serrado de un solo tronco solo con una motosierra.'::text),
(383378,42598,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que l''ours ... dans un seul tronc avec une simple tronçonneuse.'::text,'a été scié'::text,'scier'::text,'sciant'::text,'On dit que l''ours a été scié dans un seul tronc avec une simple tronçonneuse.'::text),
(383381,42598,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayının tek bir gövdeden sadece motorlu testereyle ... söyleniyor.'::text,'kesildiği'::text,'kesmek'::text,'kesme'::text,'Ayının tek bir gövdeden sadece motorlu testereyle kesildiği söyleniyor.'::text),
(383382,42598,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, a medvét ... egyetlen törzsből, csak láncfűrésszel.'::text,'fűrészelték ki'::text,'fűrészelni'::text,'fűrészelés'::text,'Azt mondják, a medvét fűrészelték ki egyetlen törzsből, csak láncfűrésszel.'::text),
(383385,42599,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er bestritt, die Beine des Bären zu dünn ...'::text,'gesägt zu haben'::text,'zu sägen'::text,'gesägt'::text,'Er bestritt, die Beine des Bären zu dünn gesägt zu haben.'::text),
(383389,42599,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він заперечив, що ... лапи ведмедя надто тонкими.'::text,'випиляв'::text,'пиляти'::text,'випиляв'::text,'Він заперечив, що випиляв лапи ведмедя надто тонкими.'::text),
(383388,42599,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negó ... las patas del oso demasiado finas.'::text,'haber serrado'::text,'serrar'::text,'serrado'::text,'Negó haber serrado las patas del oso demasiado finas.'::text),
(383387,42599,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a nié ... les pattes de l''ours trop fines.'::text,'avoir scié'::text,'scier'::text,'scié'::text,'Il a nié avoir scié les pattes de l''ours trop fines.'::text),
(383390,42599,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayının bacaklarını fazla ince ... inkâr etti.'::text,'kestiğini'::text,'kesmeyi'::text,'kesilmiş'::text,'Ayının bacaklarını fazla ince kestiğini inkâr etti.'::text),
(383391,42599,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy túl vékonyra ... a medve lábait.'::text,'fűrészelte'::text,'fűrészelni'::text,'fűrészelt'::text,'Tagadta, hogy túl vékonyra fűrészelte a medve lábait.'::text),
(383394,42600,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hätte nicht so nah an den Beinen sägen ...! Noch ein Schnitt, und der Bär ist komplett ruiniert!'::text,'sollen'::text,'dürfen'::text,'können'::text,'Er hätte nicht so nah an den Beinen sägen sollen! Noch ein Schnitt, und der Bär ist komplett ruiniert!'::text),
(383398,42600,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... пиляти так близько до лап! Ще один різ — і ведмідь повністю зіпсований!'::text,'не мав'::text,'не мусив'::text,'не міг'::text,'Він не мав пиляти так близько до лап! Ще один різ — і ведмідь повністю зіпсований!'::text),
(383397,42600,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No ... serrar tan cerca de las patas! ¡Un corte más y el oso queda totalmente arruinado!'::text,'debió'::text,'tenía que'::text,'podía'::text,'¡No debió serrar tan cerca de las patas! ¡Un corte más y el oso queda totalmente arruinado!'::text),
(383396,42600,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... scier si près des pattes ! Encore une coupe et l''ours est complètement fichu !'::text,'n''aurait pas dû'::text,'ne devait pas'::text,'ne pouvait pas'::text,'Il n''aurait pas dû scier si près des pattes ! Encore une coupe et l''ours est complètement fichu !'::text),
(383399,42600,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bacaklara o kadar yakın ...! Bir kesik daha ve ayı tamamen mahvolur!'::text,'kesmemeliydi'::text,'kesmemiş olmalı'::text,'kesemezdi'::text,'Bacaklara o kadar yakın kesmemeliydi! Bir kesik daha ve ayı tamamen mahvolur!'::text),
(383400,42600,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ... ilyen közel fűrészelnie a lábakhoz! Még egy vágás, és a medve teljesen tönkremegy!'::text,'kellett volna'::text,'volt szabad'::text,'tudott volna'::text,'Nem kellett volna ilyen közel fűrészelnie a lábakhoz! Még egy vágás, és a medve teljesen tönkremegy!'::text),
(383403,42601,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie ... jemanden so schnell einen Bären aus einem Baum sägen sehen! Absolut unglaublich!'::text,'habe ich'::text,'ich habe'::text,'habe gesehen ich'::text,'Nie habe ich jemanden so schnell einen Bären aus einem Baum sägen sehen! Absolut unglaublich!'::text),
(383407,42601,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ..., щоб хтось так швидко випиляв ведмедя з дерева! Абсолютно неймовірно!'::text,'я не бачив'::text,'я не бачив'::text,'не бачив я'::text,'Ніколи я не бачив, щоб хтось так швидко випиляв ведмедя з дерева! Абсолютно неймовірно!'::text),
(383406,42601,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca ... a nadie serrar un oso de un árbol tan rápido! ¡Absolutamente increíble!'::text,'he visto'::text,'yo he visto'::text,'visto he'::text,'¡Nunca he visto a nadie serrar un oso de un árbol tan rápido! ¡Absolutamente increíble!'::text),
(383405,42601,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... quelqu''un sortir un ours d''un arbre à la scie aussi vite ! Absolument incroyable !'::text,'je n''ai vu'::text,'j''ai vu'::text,'n''ai vu je'::text,'Jamais je n''ai vu quelqu''un sortir un ours d''un arbre à la scie aussi vite ! Absolument incroyable !'::text),
(383408,42601,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç kimsenin bir ağaçtan bu kadar hızlı ayı kestiğini ...! Kesinlikle inanılmaz!'::text,'görmedim'::text,'ben görmedim'::text,'görmedim ben'::text,'Hiç kimsenin bir ağaçtan bu kadar hızlı ayı kestiğini görmedim! Kesinlikle inanılmaz!'::text),
(383409,42601,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... senkit ilyen gyorsan medvét fűrészelni egy fából! Hihetetlen!'::text,'nem láttam'::text,'én nem láttam'::text,'láttam én nem'::text,'Soha nem láttam senkit ilyen gyorsan medvét fűrészelni egy fából! Hihetetlen!'::text),
(383412,42602,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, dass er die Rinde ... lässt, bevor er sägt.'::text,'abschneiden'::text,'abzuschneiden'::text,'abschneidend'::text,'Hör zu, er hat mir erzählt, dass er die Rinde abschneiden lässt, bevor er sägt.'::text),
(383416,42602,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що кору йому ..., перш ніж він пиляє.'::text,'зрізають'::text,'зрізати'::text,'зрізання'::text,'Слухай, він сказав мені, що кору йому зрізають, перш ніж він пиляє.'::text),
(383415,42602,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que se hace ... la corteza antes de serrar.'::text,'cortar'::text,'cortar'::text,'cortando'::text,'Oye, me dijo que se hace cortar la corteza antes de serrar.'::text),
(383414,42602,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il fait ... l''écorce avant de scier.'::text,'couper'::text,'couper'::text,'coupant'::text,'Écoute, il m''a dit qu''il fait couper l''écorce avant de scier.'::text),
(383417,42602,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana testereyle kesmeden önce kabuğu ... söyledi.'::text,'kestirdiğini'::text,'kestirdiğini'::text,'kesmesini'::text,'Dinle, bana testereyle kesmeden önce kabuğu kestirdiğini söyledi.'::text),
(383418,42602,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy fűrészelés előtt ... a kérget.'::text,'levágatja'::text,'levágatja'::text,'levágva'::text,'Figyelj, azt mondta, hogy fűrészelés előtt levágatja a kérget.'::text),
(383421,42603,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, er hat mir erzählt, er wünschte, er ... einen kleineren Stamm zum Sägen ausgesucht.'::text,'hätte'::text,'hätte'::text,'würde'::text,'Also, er hat mir erzählt, er wünschte, er hätte einen kleineren Stamm zum Sägen ausgesucht.'::text),
(383425,42603,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, він сказав мені, що хотів би, щоб ... менший стовбур для пиляння.'::text,'вибрав'::text,'вибрав'::text,'вибрав'::text,'Коротше, він сказав мені, що хотів би, щоб вибрав менший стовбур для пиляння.'::text),
(383424,42603,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bueno, me dijo que ojalá ... un tronco más pequeño para serrar.'::text,'hubiera elegido'::text,'eligiera'::text,'eligiera'::text,'Bueno, me dijo que ojalá hubiera elegido un tronco más pequeño para serrar.'::text),
(383423,42603,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, il m''a dit qu''il aimerait ... un tronc plus petit à scier.'::text,'avoir choisi'::text,'choisir'::text,'choisir'::text,'Bon, il m''a dit qu''il aimerait avoir choisi un tronc plus petit à scier.'::text),
(383426,42603,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yani, bana “Keşke kesmek için daha küçük bir gövde ...” dedi.'::text,'seçseydim'::text,'seçsem'::text,'seçeceğim'::text,'Yani, bana “Keşke kesmek için daha küçük bir gövde seçseydim” dedi.'::text),
(383427,42603,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt mondta, bárcsak egy kisebb törzset ... fűrészelni.'::text,'választott volna'::text,'választana'::text,'választana'::text,'Szóval azt mondta, bárcsak egy kisebb törzset választott volna fűrészelni.'::text),
(362739,40305,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich hat der Typ, ... seine Hose auf dem Bett gebügelt hat, kein Bügelbrett.'::text,'der'::text,'welches'::text,'dessen'::text,'Mädel, angeblich hat der Typ, der seine Hose auf dem Bett gebügelt hat, kein Bügelbrett.'::text),
(362743,40305,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, у хлопця, ... прасував штани на ліжку, немає прасувальної дошки.'::text,'який'::text,'що'::text,'чий'::text,'Подруго, кажуть, у хлопця, який прасував штани на ліжку, немає прасувальної дошки.'::text),
(362742,40305,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer el chico ... planchó los pantalones en la cama no tiene tabla de planchar.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Tía, al parecer el chico que planchó los pantalones en la cama no tiene tabla de planchar.'::text),
(362741,40305,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment le mec ... a repassé son pantalon sur le lit n''a pas de planche à repasser.'::text,'qui'::text,'lequel'::text,'dont'::text,'Meuf, apparemment le mec qui a repassé son pantalon sur le lit n''a pas de planche à repasser.'::text),
(362744,40305,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya pantolonunu yatakta ... adamın ütü masası yokmuş.'::text,'ütüleyen'::text,'ütülediği'::text,'kimin ütülediği'::text,'Kızım, güya pantolonunu yatakta ütüleyen adamın ütü masası yokmuş.'::text),
(362745,40305,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag annak a srácnak, ... az ágyon vasalta a nadrágját, nincs vasalódeszkája.'::text,'aki'::text,'amely'::text,'akinek'::text,'Csajszi, állítólag annak a srácnak, aki az ágyon vasalta a nadrágját, nincs vasalódeszkája.'::text),
(362748,40306,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie hat mir erzählt, dass sie das ganze Laken morgen noch mal ...'::text,'bügeln würde'::text,'bügeln wird'::text,'bügelt'::text,'Rate mal, sie hat mir erzählt, dass sie das ganze Laken morgen noch mal bügeln würde.'::text),
(362752,40306,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вгадай що, вона сказала мені, що завтра знову ... все те простирадло.'::text,'попрасує'::text,'попрасує'::text,'прасує'::text,'Вгадай що, вона сказала мені, що завтра знову попрасує все те простирадло.'::text),
(362751,40306,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, me dijo que mañana ... otra vez toda esa sábana.'::text,'plancharía'::text,'planchará'::text,'plancha'::text,'Adivina qué, me dijo que mañana plancharía otra vez toda esa sábana.'::text),
(362750,40306,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle m''a dit qu''elle ... tout ce drap encore demain.'::text,'repasserait'::text,'repassera'::text,'repasse'::text,'Devine quoi, elle m''a dit qu''elle repasserait tout ce drap encore demain.'::text),
(362753,40306,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, bana yarın o koca çarşafı yine ... söyledi.'::text,'ütüleyeceğini'::text,'ütüleyeceğini'::text,'ütülediğini'::text,'Bil bakalım ne oldu, bana yarın o koca çarşafı yine ütüleyeceğini söyledi.'::text),
(362754,40306,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, hogy holnap megint ... az egész lepedőt.'::text,'kivasalja'::text,'ki fogja vasalni'::text,'vasalja'::text,'Képzeld, azt mondta, hogy holnap megint kivasalja az egész lepedőt.'::text),
(362757,40307,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, früher ... du Bügeln, und jetzt sehen deine Servietten perfekt aus.'::text,'hasstest'::text,'hasstest'::text,'warst es gewohnt zu hassen'::text,'Ehrlich, früher hasstest du Bügeln, und jetzt sehen deine Servietten perfekt aus.'::text),
(362761,40307,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... ненавидів прасування, а тепер твої серветки виглядають ідеально.'::text,'раніше'::text,'бувало'::text,'звик'::text,'Чесно, ти раніше ненавидів прасування, а тепер твої серветки виглядають ідеально.'::text),
(362760,40307,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... odiar planchar, y ahora tus servilletas quedan perfectas.'::text,'solías'::text,'solías'::text,'estabas acostumbrado a'::text,'La verdad, solías odiar planchar, y ahora tus servilletas quedan perfectas.'::text),
(362759,40307,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, avant tu ... le repassage, et maintenant tes serviettes sont parfaites.'::text,'détestais'::text,'détestais'::text,'étais habitué à détester'::text,'Franchement, avant tu détestais le repassage, et maintenant tes serviettes sont parfaites.'::text),
(362762,40307,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, eskiden ütüden ..., şimdi peçetelerin kusursuz görünüyor.'::text,'nefret ederdin'::text,'nefret ederdin'::text,'nefret etmeye alışkındın'::text,'Açıkçası, eskiden ütüden nefret ederdin, şimdi peçetelerin kusursuz görünüyor.'::text),
(362763,40307,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, régen ... a vasalást, most meg tökéletesek a szalvétáid.'::text,'utáltad'::text,'utáltad'::text,'hozzá voltál szokva, hogy utáld'::text,'Őszintén, régen utáltad a vasalást, most meg tökéletesek a szalvétáid.'::text),
(362775,40309,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Laken mit zwei Bügeleisen zu bügeln ist natürlich der schnellste Weg, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Ein Laken mit zwei Bügeleisen zu bügeln ist natürlich der schnellste Weg, oder?'::text),
(362779,40309,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прасувати одне простирадло двома прасками — звісно, найшвидший спосіб, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Прасувати одне простирадло двома прасками — звісно, найшвидший спосіб, так?'::text),
(362778,40309,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Planchar una sábana con dos planchas es obviamente la forma más rápida, ...?'::text,'¿no?'::text,'¿no?'::text,'¿no?'::text,'Planchar una sábana con dos planchas es obviamente la forma más rápida, ¿no?'::text),
(362777,40309,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Repasser un drap avec deux fers, c''est évidemment le plus rapide, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Repasser un drap avec deux fers, c''est évidemment le plus rapide, non ?'::text),
(362780,40309,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir çarşafı iki ütüyle ütülemek tabii ki en hızlı yol, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil miydi?'::text,'Bir çarşafı iki ütüyle ütülemek tabii ki en hızlı yol, değil mi?'::text),
(362781,40309,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy lepedőt két vasalóval vasalni nyilván a leggyorsabb módszer, ...?'::text,'nem?'::text,'nem?'::text,'nem?'::text,'Egy lepedőt két vasalóval vasalni nyilván a leggyorsabb módszer, nem?'::text),
(362784,40310,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau bügelte ein weißes Hemd, und ...'::text,'der Mann auch.'::text,'der Mann auch.'::text,'der Mann auch.'::text,'Die Frau bügelte ein weißes Hemd, und der Mann auch.'::text),
(362788,40310,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка попрасувала білу сорочку, і ...'::text,'чоловік теж.'::text,'чоловік теж.'::text,'чоловік теж.'::text,'Жінка попрасувала білу сорочку, і чоловік теж.'::text),
(362787,40310,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer planchó una camisa blanca, y ...'::text,'el hombre también.'::text,'el hombre también.'::text,'el hombre también.'::text,'La mujer planchó una camisa blanca, y el hombre también.'::text),
(362786,40310,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme a repassé une chemise blanche, et ...'::text,'l''homme aussi.'::text,'l''homme aussi.'::text,'l''homme aussi.'::text,'La femme a repassé une chemise blanche, et l''homme aussi.'::text),
(362789,40310,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın beyaz bir gömlek ütüledi, ...'::text,'adam da öyle.'::text,'adam da öyle.'::text,'adam da öyle.'::text,'Kadın beyaz bir gömlek ütüledi, adam da öyle.'::text),
(362790,40310,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő kivasalt egy fehér inget, és ...'::text,'a férfi is.'::text,'a férfi is.'::text,'a férfi is.'::text,'A nő kivasalt egy fehér inget, és a férfi is.'::text),
(362802,40312,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Mittag ... die ältere Frau den ganzen Stapel Servietten gebügelt.'::text,'hat'::text,'bügelt'::text,'bügelt gerade'::text,'Bis zum Mittag hat die ältere Frau den ganzen Stapel Servietten gebügelt.'::text),
(362806,40312,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду старша жінка ... всю стопку серветок.'::text,'попрасує'::text,'попрасує'::text,'прасуватиме'::text,'До обіду старша жінка попрасує всю стопку серветок.'::text),
(362805,40312,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la hora de comer, la mujer mayor ... toda la pila de servilletas.'::text,'habrá planchado'::text,'planchará'::text,'estará planchando'::text,'Para la hora de comer, la mujer mayor habrá planchado toda la pila de servilletas.'::text),
(362804,40312,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, la femme plus âgée ... toute la pile de serviettes.'::text,'aura repassé'::text,'repassera'::text,'sera en train de repasser'::text,'D''ici midi, la femme plus âgée aura repassé toute la pile de serviettes.'::text),
(362807,40312,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğle yemeğine kadar yaşlı kadın bütün peçete yığınını ...'::text,'ütülemiş olacak'::text,'ütüleyecek'::text,'ütülüyor olacak'::text,'Öğle yemeğine kadar yaşlı kadın bütün peçete yığınını ütülemiş olacak.'::text),
(362808,40312,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebédre az idősebb nő ... az egész szalvétakupacot.'::text,'kivasalja'::text,'kivasalja'::text,'vasalni fogja'::text,'Ebédre az idősebb nő kivasalja az egész szalvétakupacot.'::text),
(362811,40313,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um sechs Uhr ... sie dieses endlose Laken schon drei Stunden lang! Ein Albtraum!'::text,'bügeln'::text,'bügeln'::text,'haben gebügelt'::text,'Um sechs Uhr bügeln sie dieses endlose Laken schon drei Stunden lang! Ein Albtraum!'::text),
(362815,40313,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О шостій вони вже три години ... це нескінченне простирадло! Жах!'::text,'прасуватимуть'::text,'прасуватимуть'::text,'попрасують'::text,'О шостій вони вже три години прасуватимуть це нескінченне простирадло! Жах!'::text),
(362814,40313,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡A las seis, ... tres horas planchando esta sábana interminable! ¡Una pesadilla!'::text,'llevarán'::text,'estarán'::text,'habrán'::text,'¡A las seis, llevarán tres horas planchando esta sábana interminable! ¡Una pesadilla!'::text),
(362813,40313,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À six heures, ils ... ce drap interminable depuis trois heures ! Un cauchemar !'::text,'repasseront'::text,'repasseront'::text,'auront repassé'::text,'À six heures, ils repasseront ce drap interminable depuis trois heures ! Un cauchemar !'::text),
(362816,40313,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat altıya kadar bu bitmek bilmeyen çarşafı üç saattir ...! Kâbus!'::text,'ütülüyor olacaklar'::text,'ütülüyor olacaklar'::text,'ütülemiş olacaklar'::text,'Saat altıya kadar bu bitmek bilmeyen çarşafı üç saattir ütülüyor olacaklar! Kâbus!'::text),
(362817,40313,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hatkor már három órája ... ezt a végtelen lepedőt! Rémálom!'::text,'vasalják'::text,'vasalják'::text,'ki fogják vasalni'::text,'Hatkor már három órája vasalják ezt a végtelen lepedőt! Rémálom!'::text),
(362820,40314,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie das Hemd nicht gebügelt hätte, ... das Meeting eine totale Katastrophe gewesen!'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn sie das Hemd nicht gebügelt hätte, wäre das Meeting eine totale Katastrophe gewesen!'::text),
(362824,40314,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не попрасувала ту сорочку, зустріч ... повною катастрофою!'::text,'була б'::text,'буде'::text,'була'::text,'Якби вона не попрасувала ту сорочку, зустріч була б повною катастрофою!'::text),
(362823,40314,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si no hubiera planchado esa camisa, la reunión ... un desastre total!'::text,'habría sido'::text,'será'::text,'fue'::text,'¡Si no hubiera planchado esa camisa, la reunión habría sido un desastre total!'::text),
(362822,40314,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas repassé cette chemise, la réunion ... une catastrophe totale !'::text,'aurait été'::text,'sera'::text,'a été'::text,'Si elle n''avait pas repassé cette chemise, la réunion aurait été une catastrophe totale !'::text),
(362825,40314,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O gömleği ütülemeseydi toplantı tam bir felaket ...!'::text,'olurdu'::text,'olacak'::text,'oldu'::text,'O gömleği ütülemeseydi toplantı tam bir felaket olurdu!'::text),
(362826,40314,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem vasalta volna ki azt az inget, a megbeszélés totális katasztrófa ...!'::text,'lett volna'::text,'lesz'::text,'volt'::text,'Ha nem vasalta volna ki azt az inget, a megbeszélés totális katasztrófa lett volna!'::text),
(362829,40315,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das große weiße Laken soll von zwei Frauen gleichzeitig ...'::text,'gebügelt worden sein'::text,'bügeln'::text,'bügelnd'::text,'Das große weiße Laken soll von zwei Frauen gleichzeitig gebügelt worden sein.'::text),
(362833,40315,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що велике біле простирадло ... двома жінками одночасно.'::text,'було попрасоване'::text,'прасувати'::text,'прасування'::text,'Кажуть, що велике біле простирадло було попрасоване двома жінками одночасно.'::text),
(362832,40315,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que la gran sábana blanca ... por dos mujeres a la vez.'::text,'fue planchada'::text,'planchar'::text,'planchando'::text,'Se dice que la gran sábana blanca fue planchada por dos mujeres a la vez.'::text),
(362831,40315,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que le grand drap blanc ... par deux femmes en même temps.'::text,'a été repassé'::text,'repasser'::text,'repassant'::text,'On dit que le grand drap blanc a été repassé par deux femmes en même temps.'::text),
(362834,40315,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük beyaz çarşafın aynı anda iki kadın tarafından ... söyleniyor.'::text,'ütülendiği'::text,'ütülemek'::text,'ütüleme'::text,'Büyük beyaz çarşafın aynı anda iki kadın tarafından ütülendiği söyleniyor.'::text),
(362835,40315,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, a nagy fehér lepedőt két nő ... egyszerre.'::text,'vasalta ki'::text,'vasalni'::text,'vasalás'::text,'Azt mondják, a nagy fehér lepedőt két nő vasalta ki egyszerre.'::text),
(357807,39757,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gab zu, ein Zahnrad aus der alten Waschmaschine für seine Erfindung ...'::text,'genommen zu haben'::text,'zu nehmen'::text,'genommen'::text,'Er gab zu, ein Zahnrad aus der alten Waschmaschine für seine Erfindung genommen zu haben.'::text),
(357811,39757,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зізнався, що ... зубчасте колесо зі старої пральної машини для свого винаходу.'::text,'взяв'::text,'взяти'::text,'взятий'::text,'Він зізнався, що взяв зубчасте колесо зі старої пральної машини для свого винаходу.'::text),
(357810,39757,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitió ... un engranaje de la vieja lavadora para su invento.'::text,'haber cogido'::text,'coger'::text,'cogido'::text,'Admitió haber cogido un engranaje de la vieja lavadora para su invento.'::text),
