(357812,39757,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buluşu için eski çamaşır makinesinden bir dişli ... itiraf etti.'::text,'aldığını'::text,'almayı'::text,'alınmış'::text,'Buluşu için eski çamaşır makinesinden bir dişli aldığını itiraf etti.'::text),
(357813,39757,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beismerte, hogy ... egy fogaskereket a régi mosógépből a találmányához.'::text,'kivett'::text,'kivenni'::text,'kivéve'::text,'Beismerte, hogy kivett egy fogaskereket a régi mosógépből a találmányához.'::text),
(357816,39758,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Maschine blieb plötzlich stehen, also ... sich darin ein Zahnrad gelöst haben.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Die Maschine blieb plötzlich stehen, also muss sich darin ein Zahnrad gelöst haben.'::text),
(357820,39758,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Машина раптом зупинилася, тож зубчасте колесо в ній ... розкрутитися.'::text,'мусило'::text,'мало'::text,'не могло'::text,'Машина раптом зупинилася, тож зубчасте колесо в ній мусило розкрутитися.'::text),
(357819,39758,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La máquina se paró de repente, así que un engranaje ... soltado dentro.'::text,'debe de haberse'::text,'debería haberse'::text,'no puede haberse'::text,'La máquina se paró de repente, así que un engranaje debe de haberse soltado dentro.'::text),
(357818,39758,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La machine s''est arrêtée d''un coup, donc un engrenage ... se desserrer à l''intérieur.'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'La machine s''est arrêtée d''un coup, donc un engrenage a dû se desserrer à l''intérieur.'::text),
(357821,39758,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makine aniden durdu, yani içinde bir dişli ...'::text,'gevşemiş olmalı'::text,'gevşemeliydi'::text,'gevşemiş olamaz'::text,'Makine aniden durdu, yani içinde bir dişli gevşemiş olmalı.'::text),
(357822,39758,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gép hirtelen leállt, tehát egy fogaskerék ... meglazult benne.'::text,'biztos'::text,'kellett volna'::text,'nem lehet, hogy'::text,'A gép hirtelen leállt, tehát egy fogaskerék biztos meglazult benne.'::text),
(357825,39759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie ... er eine Maschine mit so vielen Zahnrädern gesehen, absolut nie!'::text,'hatte'::text,'er hatte'::text,'tat'::text,'Nie hatte er eine Maschine mit so vielen Zahnrädern gesehen, absolut nie!'::text),
(357829,39759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ... машини з такою кількістю зубчастих коліс, абсолютно ніколи!'::text,'він не бачив'::text,'він не бачив'::text,'не бачив'::text,'Ніколи він не бачив машини з такою кількістю зубчастих коліс, абсолютно ніколи!'::text),
(357828,39759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca ... una máquina con tantos engranajes, absolutamente nunca!'::text,'había visto'::text,'él había visto'::text,'vio'::text,'¡Nunca había visto una máquina con tantos engranajes, absolutamente nunca!'::text),
(357827,39759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... une machine avec autant d''engrenages, absolument jamais !'::text,'il n''avait vu'::text,'il avait vu'::text,'il ne vit'::text,'Jamais il n''avait vu une machine avec autant d''engrenages, absolument jamais !'::text),
(357830,39759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç bu kadar çok dişlisi olan bir makine ..., kesinlikle hiç!'::text,'görmemişti'::text,'o görmemişti'::text,'görmedi'::text,'Hiç bu kadar çok dişlisi olan bir makine görmemişti, kesinlikle hiç!'::text),
(357831,39759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... még ennyi fogaskerekű gépet, soha az életben!'::text,'nem látott'::text,'ő nem látott'::text,'nem látott'::text,'Soha nem látott még ennyi fogaskerekű gépet, soha az életben!'::text),
(357834,39760,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich hat er seinen Cousin dazu gebracht, jedes Zahnrad an dieser riesigen Maschine ...'::text,'zu ölen'::text,'ölen'::text,'ölend'::text,'Mädel, angeblich hat er seinen Cousin dazu gebracht, jedes Zahnrad an dieser riesigen Maschine zu ölen.'::text),
(357838,39760,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він змусив кузена ... кожне зубчасте колесо на тій величезній машині.'::text,'змастити'::text,'змастити'::text,'змащування'::text,'Подруго, кажуть, він змусив кузена змастити кожне зубчасте колесо на тій величезній машині.'::text),
