(357836,39760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il a fait ... chaque engrenage de cette énorme machine par son cousin.'::text,'huiler'::text,'huiler'::text,'huilant'::text,'Meuf, apparemment il a fait huiler chaque engrenage de cette énorme machine par son cousin.'::text),
(357839,39760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya kuzenine o dev makinedeki her dişliyi ...'::text,'yağlatmış'::text,'yağlatmış'::text,'yağlama'::text,'Kızım, güya kuzenine o dev makinedeki her dişliyi yağlatmış.'::text),
