(396934,44104,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... на крихітну шестірню крізь лупу, коли пробив підлоговий годинник.'::text,'дивилася'::text,'подивилася'::text,'подивилася'::text,'Вона дивилася на крихітну шестірню крізь лупу, коли пробив підлоговий годинник.'::text),
(396933,44104,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un engranaje diminuto con su lupa cuando dio la hora el reloj de pie.'::text,'Estaba mirando'::text,'Miró'::text,'Ha mirado'::text,'Estaba mirando un engranaje diminuto con su lupa cuando dio la hora el reloj de pie.'::text),
(396932,44104,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... un minuscule engrenage à la loupe quand l''horloge comtoise a sonné.'::text,'regardait'::text,'a regardé'::text,'a regardé'::text,'Elle regardait un minuscule engrenage à la loupe quand l''horloge comtoise a sonné.'::text),
(396935,44104,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük saat çaldığında lupuyla minicik bir dişliye ...'::text,'bakıyordu'::text,'baktı'::text,'baktı'::text,'Büyük saat çaldığında lupuyla minicik bir dişliye bakıyordu.'::text),
(396936,44104,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp egy apró fogaskereket ... a nagyítóján át, amikor ütött az állóóra.'::text,'nézett'::text,'nézett meg'::text,'megnézett'::text,'Épp egy apró fogaskereket nézett a nagyítóján át, amikor ütött az állóóra.'::text),
(396948,44106,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, sie hat mir erzählt, dass sie gerade das winzige Zahnrad ..., als ihr plötzlich die Pinzette abrutschte.'::text,'hielt'::text,'hielt'::text,'gehalten hat'::text,'Also, sie hat mir erzählt, dass sie gerade das winzige Zahnrad hielt, als ihr plötzlich die Pinzette abrutschte.'::text),
(396952,44106,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, вона сказала мені, що ... крихітну шестірню, коли пінцет раптом зісковзнув.'::text,'тримала'::text,'тримала'::text,'тримала'::text,'Коротше, вона сказала мені, що тримала крихітну шестірню, коли пінцет раптом зісковзнув.'::text),
(396951,44106,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bueno, me dijo que ... el engranaje diminuto cuando de repente se le resbalaron las pinzas.'::text,'sostenía'::text,'sostuvo'::text,'ha sostenido'::text,'Bueno, me dijo que sostenía el engranaje diminuto cuando de repente se le resbalaron las pinzas.'::text),
(396950,44106,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, elle m''a dit qu''elle ... le minuscule engrenage quand sa pince a soudain glissé.'::text,'tenait'::text,'a tenu'::text,'a tenu'::text,'Bon, elle m''a dit qu''elle tenait le minuscule engrenage quand sa pince a soudain glissé.'::text),
(396953,44106,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yani, bana cımbızı aniden kaydığında minicik dişliyi ... söyledi.'::text,'tuttuğunu'::text,'tuttuğunu'::text,'tuttuğunu'::text,'Yani, bana cımbızı aniden kaydığında minicik dişliyi tuttuğunu söyledi.'::text),
(396954,44106,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt mondta, hogy épp ... az apró fogaskereket, amikor hirtelen megcsúszott a csipesze.'::text,'tartotta'::text,'tartotta'::text,'tartotta'::text,'Szóval azt mondta, hogy épp tartotta az apró fogaskereket, amikor hirtelen megcsúszott a csipesze.'::text),
(396957,44107,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... heute so fünfzig winzige Zahnräder repariert, lowkey legendär.'::text,'hat'::text,'hat'::text,'repariert'::text,'Bro, sie hat heute so fünfzig winzige Zahnräder repariert, lowkey legendär.'::text),
(396961,44107,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона сьогодні ... десь п''ятдесят крихітних шестірень, лоукі легенда.'::text,'полагодила'::text,'лагодила'::text,'лагодить'::text,'Бро, вона сьогодні полагодила десь п''ятдесят крихітних шестірень, лоукі легенда.'::text),
(396960,44107,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, hoy ... como cincuenta engranajes diminutos, una crack.'::text,'ha arreglado'::text,'ha estado arreglando'::text,'está arreglando'::text,'Bro, hoy ha arreglado como cincuenta engranajes diminutos, una crack.'::text),
(396959,44107,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... genre cinquante minuscules engrenages aujourd''hui, grave légendaire.'::text,'a réparé'::text,'répare'::text,'répare'::text,'Frérot, elle a réparé genre cinquante minuscules engrenages aujourd''hui, grave légendaire.'::text),
(396962,44107,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bugün elli tane minicik dişli ..., baya efsane.'::text,'tamir etti'::text,'tamir ediyor'::text,'tamir ediyor'::text,'Kanka, bugün elli tane minicik dişli tamir etti, baya efsane.'::text),
(396963,44107,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ma vagy ötven apró fogaskereket ... meg, lowkey legenda.'::text,'javított'::text,'javítgatott'::text,'javít'::text,'Tesó, ma vagy ötven apró fogaskereket javított meg, lowkey legenda.'::text),
(396966,44108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, als sie die Lupe schnappte, ... sie das winzige Zahnrad schon aufgehoben, kein Witz.'::text,'hatte'::text,'hat'::text,'hebt'::text,'Bro, als sie die Lupe schnappte, hatte sie das winzige Zahnrad schon aufgehoben, kein Witz.'::text),
(396970,44108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, поки вона схопила лупу, вона вже ... ту крихітну шестірню, без жартів.'::text,'підняла'::text,'підняла'::text,'піднімає'::text,'Бро, поки вона схопила лупу, вона вже підняла ту крихітну шестірню, без жартів.'::text),
(396969,44108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, cuando agarró la lupa, ya ... ese engranaje diminuto, en serio.'::text,'había cogido'::text,'ha cogido'::text,'coge'::text,'Bro, cuando agarró la lupa, ya había cogido ese engranaje diminuto, en serio.'::text),
(396968,44108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le temps qu''elle attrape la loupe, elle ... déjà ce minuscule engrenage, sans mentir.'::text,'avait ramassé'::text,'a ramassé'::text,'ramasse'::text,'Frérot, le temps qu''elle attrape la loupe, elle avait ramassé déjà ce minuscule engrenage, sans mentir.'::text),
(396971,44108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, lupu kaptığında o minicik dişliyi çoktan ..., yalan yok.'::text,'almıştı'::text,'aldı'::text,'alır'::text,'Kanka, lupu kaptığında o minicik dişliyi çoktan almıştı, yalan yok.'::text),
(396972,44108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire megragadta a nagyítót, azt az apró fogaskereket már ..., komolyan.'::text,'felvette'::text,'felvette'::text,'felveszi'::text,'Tesó, mire megragadta a nagyítót, azt az apró fogaskereket már felvette, komolyan.'::text),
(396975,44109,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das winzige Zahnrad, ... Preis 40 Euro beträgt, kommt in die Kaminuhr des Kunden.'::text,'dessen'::text,'das'::text,'welches'::text,'Das winzige Zahnrad, dessen Preis 40 Euro beträgt, kommt in die Kaminuhr des Kunden.'::text),
(396979,44109,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Крихітна шестірня, ... ціна 40 євро, піде в камінний годинник клієнта.'::text,'чия'::text,'яка'::text,'що'::text,'Крихітна шестірня, чия ціна 40 євро, піде в камінний годинник клієнта.'::text),
(396978,44109,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El engranaje diminuto, ... precio es de 40 euros, va en el reloj de chimenea del cliente.'::text,'cuyo'::text,'que'::text,'el cual'::text,'El engranaje diminuto, cuyo precio es de 40 euros, va en el reloj de chimenea del cliente.'::text),
(396977,44109,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le minuscule engrenage, ... le prix est de 40 euros, va dans la pendule de cheminée du client.'::text,'dont'::text,'qui'::text,'que'::text,'Le minuscule engrenage, dont le prix est de 40 euros, va dans la pendule de cheminée du client.'::text),
(396980,44109,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fiyatı 40 avro ... minicik dişli, müşterinin şömine saatine takılacak.'::text,'olan'::text,'olan'::text,'olan'::text,'Fiyatı 40 avro olan minicik dişli, müşterinin şömine saatine takılacak.'::text),
(396981,44109,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az apró fogaskerék, ... ára 40 euró, az ügyfél kandallóórájába kerül.'::text,'amelynek az'::text,'amely'::text,'ami'::text,'Az apró fogaskerék, amelynek az ára 40 euró, az ügyfél kandallóórájába kerül.'::text),
(396993,44111,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Uhrmacherin wusste, dass das winzige Zahnrad eine Lupe ..., wie es bei solchen Teilen typischerweise der Fall ist.'::text,'brauchen würde'::text,'brauchen wird'::text,'braucht'::text,'Die Uhrmacherin wusste, dass das winzige Zahnrad eine Lupe brauchen würde, wie es bei solchen Teilen typischerweise der Fall ist.'::text),
(396997,44111,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Годинникарка знала, що крихітній шестірні ... лупа, як це типово буває з такими деталями.'::text,'знадобиться'::text,'знадобиться'::text,'потрібна'::text,'Годинникарка знала, що крихітній шестірні знадобиться лупа, як це типово буває з такими деталями.'::text),
(396996,44111,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La relojera sabía que el engranaje diminuto ... una lupa, como suele ocurrir con esas piezas.'::text,'necesitaría'::text,'necesitará'::text,'necesita'::text,'La relojera sabía que el engranaje diminuto necesitaría una lupa, como suele ocurrir con esas piezas.'::text),
(396995,44111,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''horlogère savait que le minuscule engrenage ... une loupe, comme c''est typiquement le cas pour ces pièces.'::text,'nécessiterait'::text,'nécessitera'::text,'nécessite'::text,'L''horlogère savait que le minuscule engrenage nécessiterait une loupe, comme c''est typiquement le cas pour ces pièces.'::text),
(396998,44111,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saatçi, bu tür parçalarda tipik olduğu gibi minicik dişlinin lup ... biliyordu.'::text,'gerektireceğini'::text,'gerektireceğini'::text,'gerektirdiğini'::text,'Saatçi, bu tür parçalarda tipik olduğu gibi minicik dişlinin lup gerektireceğini biliyordu.'::text),
(396999,44111,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az órásnő tudta, hogy az apró fogaskerékhez nagyító ..., ahogy az ilyen alkatrészeknél jellemzően lenni szokott.'::text,'kell majd'::text,'kell majd'::text,'kell'::text,'Az órásnő tudta, hogy az apró fogaskerékhez nagyító kell majd, ahogy az ilyen alkatrészeknél jellemzően lenni szokott.'::text),
(397002,44112,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... immer mit winzigen Zahnrädern um, als wär''s nichts.'::text,'gehst'::text,'bist'::text,'umgehend'::text,'Ehrlich, du gehst immer mit winzigen Zahnrädern um, als wär''s nichts.'::text),
(397006,44112,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти завжди ... з крихітними шестірнями так, ніби це дрібниця.'::text,'справляєшся'::text,'справлялася'::text,'справляння'::text,'Чесно, ти завжди справляєшся з крихітними шестірнями так, ніби це дрібниця.'::text),
(397005,44112,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, siempre ... los engranajes diminutos como si nada.'::text,'manejas'::text,'has manejado'::text,'manejando'::text,'La verdad, siempre manejas los engranajes diminutos como si nada.'::text),
(397004,44112,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... toujours les minuscules engrenages comme si de rien n''était.'::text,'manies'::text,'as manié'::text,'maniant'::text,'Franchement, tu manies toujours les minuscules engrenages comme si de rien n''était.'::text),
(397007,44112,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, minicik dişlilerle hep hiçbir şey değilmiş gibi ...'::text,'uğraşıyorsun'::text,'uğraştın'::text,'uğraşma'::text,'Açıkçası, minicik dişlilerle hep hiçbir şey değilmiş gibi uğraşıyorsun.'::text),
(397008,44112,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te mindig úgy ... az apró fogaskerekeket, mintha semmiség lenne.'::text,'kezeled'::text,'kezelted'::text,'kezelés'::text,'Őszintén, te mindig úgy kezeled az apró fogaskerekeket, mintha semmiség lenne.'::text),
(397011,44113,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade das winzige Zahnrad unter der Lupe, als sie einen Riss bemerkte.'::text,'prüfte'::text,'hat geprüft'::text,'prüft'::text,'Sie prüfte gerade das winzige Zahnrad unter der Lupe, als sie einen Riss bemerkte.'::text),
(397015,44113,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... крихітну шестірню під лупою, коли помітила тріщину.'::text,'перевіряла'::text,'перевірила'::text,'перевіряє'::text,'Вона перевіряла крихітну шестірню під лупою, коли помітила тріщину.'::text),
(397014,44113,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el engranaje diminuto bajo la lupa cuando vio una grieta.'::text,'Estaba revisando'::text,'Ha revisado'::text,'Revisa'::text,'Estaba revisando el engranaje diminuto bajo la lupa cuando vio una grieta.'::text),
(397013,44113,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le minuscule engrenage sous la loupe quand elle a remarqué une fissure.'::text,'vérifiait'::text,'a vérifié'::text,'vérifie'::text,'Elle vérifiait le minuscule engrenage sous la loupe quand elle a remarqué une fissure.'::text),
(397016,44113,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir çatlak fark ettiğinde minicik dişliyi lupun altında ...'::text,'kontrol ediyordu'::text,'kontrol etti'::text,'kontrol eder'::text,'Bir çatlak fark ettiğinde minicik dişliyi lupun altında kontrol ediyordu.'::text),
(397017,44113,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... az apró fogaskereket a nagyító alatt, amikor észrevett egy repedést.'::text,'ellenőrizte'::text,'ellenőrizte'::text,'ellenőrzi'::text,'Épp ellenőrizte az apró fogaskereket a nagyító alatt, amikor észrevett egy repedést.'::text),
(397020,44114,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Freitag ... sie jedes winzige Zahnrad in der Kaminuhr gereinigt.'::text,'hat'::text,'wird'::text,'reinigt'::text,'Bis Freitag hat sie jedes winzige Zahnrad in der Kaminuhr gereinigt.'::text),
(397024,44114,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До п''ятниці вона ... кожну крихітну шестірню в камінному годиннику.'::text,'почистить'::text,'почистить'::text,'чистить'::text,'До п''ятниці вона почистить кожну крихітну шестірню в камінному годиннику.'::text),
(397023,44114,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el viernes, ... cada engranaje diminuto del reloj de chimenea.'::text,'habrá limpiado'::text,'limpiará'::text,'limpia'::text,'Para el viernes, habrá limpiado cada engranaje diminuto del reloj de chimenea.'::text),
(397022,44114,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici vendredi, elle ... chaque minuscule engrenage de la pendule.'::text,'aura nettoyé'::text,'nettoiera'::text,'nettoie'::text,'D''ici vendredi, elle aura nettoyé chaque minuscule engrenage de la pendule.'::text),
(397025,44114,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cumaya kadar şömine saatindeki her minicik dişliyi ...'::text,'temizlemiş olacak'::text,'temizleyecek'::text,'temizler'::text,'Cumaya kadar şömine saatindeki her minicik dişliyi temizlemiş olacak.'::text),
(397026,44114,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Péntekre ... a kandallóóra minden apró fogaskerekét.'::text,'kitisztítja'::text,'kitisztítja'::text,'tisztítja'::text,'Péntekre kitisztítja a kandallóóra minden apró fogaskerekét.'::text),
(390657,43407,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich lüg nicht, wenn du noch einen Dominostein hinzufügst, ... deine Spirale perfekt.'::text,'ist'::text,'wäre'::text,'war'::text,'Ich lüg nicht, wenn du noch einen Dominostein hinzufügst, ist deine Spirale perfekt.'::text),
(390661,43407,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, якщо додаси ще одну доміношку, твоя спіраль ... ідеальною.'::text,'буде'::text,'була б'::text,'була'::text,'Не буду брехати, якщо додаси ще одну доміношку, твоя спіраль буде ідеальною.'::text),
(390660,43407,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, si añades una ficha más, tu espiral ... perfecta.'::text,'será'::text,'sería'::text,'fue'::text,'No voy a mentir, si añades una ficha más, tu espiral será perfecta.'::text),
(390659,43407,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, si tu ajoutes un domino de plus, ta spirale ... parfaite.'::text,'sera'::text,'serait'::text,'était'::text,'Je vais pas mentir, si tu ajoutes un domino de plus, ta spirale sera parfaite.'::text),
(390662,43407,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bir domino daha eklersen spiralin kusursuz ...'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Yalan yok, bir domino daha eklersen spiralin kusursuz olacak.'::text),
(390663,43407,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ha hozzáteszel még egy dominót, a spirálod tökéletes ...'::text,'lesz'::text,'lenne'::text,'volt'::text,'Nem hazudok, ha hozzáteszel még egy dominót, a spirálod tökéletes lesz.'::text),
(390666,43408,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er jetzt niesen würde, ... die ganze Spirale um. Ein sehr entspannendes Hobby, klar.'::text,'fiele'::text,'fällt'::text,'fällt'::text,'Wenn er jetzt niesen würde, fiele die ganze Spirale um. Ein sehr entspannendes Hobby, klar.'::text),
(390670,43408,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він зараз чхнув, уся спіраль ... додолу. Дуже розслабливе хобі, звісно.'::text,'впала б'::text,'впаде'::text,'падає'::text,'Якби він зараз чхнув, уся спіраль впала б додолу. Дуже розслабливе хобі, звісно.'::text),
(390669,43408,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si estornudara ahora, toda la espiral ... al suelo. Una afición muy relajante, obviamente.'::text,'se caería'::text,'se caerá'::text,'se cae'::text,'Si estornudara ahora, toda la espiral se caería al suelo. Una afición muy relajante, obviamente.'::text),
(390668,43408,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il éternuait maintenant, toute la spirale ... par terre. Un passe-temps très relaxant, évidemment.'::text,'tomberait'::text,'tombera'::text,'tombe'::text,'S''il éternuait maintenant, toute la spirale tomberait par terre. Un passe-temps très relaxant, évidemment.'::text),
(390671,43408,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdi hapşırsa bütün spiral ..., çok rahatlatıcı bir hobi tabii.'::text,'yıkılırdı'::text,'yıkılacak'::text,'yıkılır'::text,'Şimdi hapşırsa bütün spiral yıkılırdı, çok rahatlatıcı bir hobi tabii.'::text),
(390672,43408,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha most tüsszentene, az egész spirál ..., nagyon pihentető hobbi, persze.'::text,'összedőlne'::text,'összedől'::text,'összedől'::text,'Ha most tüsszentene, az egész spirál összedőlne, nagyon pihentető hobbi, persze.'::text),
(390684,43410,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... jeden Dominostein der Spirale von Hand. Etwas lustiger als ein Handyspiel.'::text,'stellte'::text,'wurde gestellt'::text,'stellend'::text,'Er stellte jeden Dominostein der Spirale von Hand. Etwas lustiger als ein Handyspiel.'::text),
(390688,43410,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... кожну доміношку спіралі вручну. Трішки веселіше, ніж гра на телефоні.'::text,'поставив'::text,'був поставлений'::text,'ставлення'::text,'Він поставив кожну доміношку спіралі вручну. Трішки веселіше, ніж гра на телефоні.'::text),
(390687,43410,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cada ficha de la espiral a mano. Algo más divertido que un juego del móvil.'::text,'Colocó'::text,'Fue colocado'::text,'Colocando'::text,'Colocó cada ficha de la espiral a mano. Algo más divertido que un juego del móvil.'::text),
(390686,43410,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... chaque domino de la spirale à la main. Un peu plus fun qu''un jeu sur téléphone.'::text,'a placé'::text,'a été placé'::text,'plaçant'::text,'Il a placé chaque domino de la spirale à la main. Un peu plus fun qu''un jeu sur téléphone.'::text),
(390689,43410,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Spiralin her dominosunu tek tek elle ..., telefon oyunundan biraz daha eğlenceli.'::text,'dizdi'::text,'dizildi'::text,'dizme'::text,'Spiralin her dominosunu tek tek elle dizdi, telefon oyunundan biraz daha eğlenceli.'::text),
(390690,43410,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kézzel ... le a spirál minden dominóját. Kicsit viccesebb, mint egy telefonos játék.'::text,'rakta'::text,'lett rakva'::text,'rakás'::text,'Kézzel rakta le a spirál minden dominóját. Kicsit viccesebb, mint egy telefonos játék.'::text),
(390693,43411,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Spirale ist fast fertig, also ... er inzwischen sehr müde sein.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Die Spirale ist fast fertig, also muss er inzwischen sehr müde sein.'::text),
(390697,43411,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спіраль майже готова, тож він ... бути вже дуже втомленим.'::text,'має'::text,'не може'::text,'не повинен'::text,'Спіраль майже готова, тож він має бути вже дуже втомленим.'::text),
(390696,43411,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La espiral está casi terminada, así que ... estar muy cansado ya.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'La espiral está casi terminada, así que debe de estar muy cansado ya.'::text),
(390695,43411,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La spirale est presque finie, donc il ... être très fatigué maintenant.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'La spirale est presque finie, donc il doit être très fatigué maintenant.'::text),
(390698,43411,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Spiral neredeyse bitti, yani şu an çok yorgun ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Spiral neredeyse bitti, yani şu an çok yorgun olmalı.'::text),
(390699,43411,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A spirál majdnem kész, úgyhogy mostanra ... nagyon fáradt.'::text,'biztos'::text,'nem lehet'::text,'nem kéne legyen'::text,'A spirál majdnem kész, úgyhogy mostanra biztos nagyon fáradt.'::text),
(390702,43412,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Spirale, ... er aus Dominosteinen gebaut hat, füllt die leere Halle.'::text,'die'::text,'wer'::text,'deren'::text,'Die Spirale, die er aus Dominosteinen gebaut hat, füllt die leere Halle.'::text),
(390706,43412,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спіраль, ... він збудував із доміно, заповнює порожню залу.'::text,'яку'::text,'хто'::text,'чия'::text,'Спіраль, яку він збудував із доміно, заповнює порожню залу.'::text),
(390705,43412,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La espiral ... construyó con fichas de dominó llena el pabellón vacío.'::text,'que'::text,'quien'::text,'cuya'::text,'La espiral que construyó con fichas de dominó llena el pabellón vacío.'::text),
(390704,43412,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La spirale ... a construite avec des dominos remplit la salle vide.'::text,'qu''il'::text,'qui il'::text,'dont il'::text,'La spirale qu''il a construite avec des dominos remplit la salle vide.'::text),
(390707,43412,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dominolardan ... spiral boş salonu dolduruyor.'::text,'yaptığı'::text,'kimin yaptığı'::text,'kimin'::text,'Dominolardan yaptığı spiral boş salonu dolduruyor.'::text),
(390708,43412,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A spirál, ... dominókból épített, betölti az üres csarnokot.'::text,'amelyet'::text,'aki'::text,'amelynek'::text,'A spirál, amelyet dominókból épített, betölti az üres csarnokot.'::text),
(390711,43413,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, dass er die Spirale vor dem Mittagessen ...'::text,'fertigstellen würde'::text,'fertigstellen wird'::text,'fertigstellt'::text,'Er sagte, dass er die Spirale vor dem Mittagessen fertigstellen würde.'::text),
(390715,43413,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що ... спіраль до обіду.'::text,'закінчить'::text,'закінчить'::text,'закінчує'::text,'Він сказав, що закінчить спіраль до обіду.'::text),
(390714,43413,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... la espiral antes de comer.'::text,'terminaría'::text,'terminará'::text,'termina'::text,'Dijo que terminaría la espiral antes de comer.'::text),
(390713,43413,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit qu''il ... la spirale avant le déjeuner.'::text,'finirait'::text,'finira'::text,'finit'::text,'Il a dit qu''il finirait la spirale avant le déjeuner.'::text),
(390716,43413,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Spirali öğle yemeğinden önce ... söyledi.'::text,'bitireceğini'::text,'bitireceğini'::text,'bitirdiğini'::text,'Spirali öğle yemeğinden önce bitireceğini söyledi.'::text),
(390717,43413,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy ebéd előtt ... a spirált.'::text,'befejezi'::text,'be fogja fejezni'::text,'fejezi be'::text,'Azt mondta, hogy ebéd előtt befejezi a spirált.'::text),
(390720,43414,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade Linien, aber jetzt mag er Spiralen, weil sie nicht gerade sind.'::text,'mochte früher'::text,'mochte'::text,'war gewohnt, zu mögen'::text,'Er mochte früher gerade Linien, aber jetzt mag er Spiralen, weil sie nicht gerade sind.'::text),
(390724,43414,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Раніше він ... прямі лінії, а тепер любить спіралі, бо вони не прямі.'::text,'любив'::text,'любив'::text,'звик любити'::text,'Раніше він любив прямі лінії, а тепер любить спіралі, бо вони не прямі.'::text),
(390723,43414,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... preferir las líneas rectas, pero ahora le gustan las espirales porque no son rectas.'::text,'Solía'::text,'Solía'::text,'Estaba acostumbrado a'::text,'Solía preferir las líneas rectas, pero ahora le gustan las espirales porque no son rectas.'::text),
(390722,43414,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, il ... les lignes droites, mais maintenant il aime les spirales parce qu''elles ne sont pas droites.'::text,'aimait'::text,'aimait'::text,'était habitué à aimer'::text,'Avant, il aimait les lignes droites, mais maintenant il aime les spirales parce qu''elles ne sont pas droites.'::text),
(390725,43414,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden düz çizgileri ..., ama şimdi spiralleri seviyor çünkü düz değiller.'::text,'severdi'::text,'severdi'::text,'sevmeye alışkındı'::text,'Eskiden düz çizgileri severdi, ama şimdi spiralleri seviyor çünkü düz değiller.'::text),
(390726,43414,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... az egyenes vonalakat, de most a spirálokat szereti, mert nem egyenesek.'::text,'szerette'::text,'szerette'::text,'hozzá volt szokva, hogy szeresse'::text,'Régen szerette az egyenes vonalakat, de most a spirálokat szereti, mert nem egyenesek.'::text),
(390729,43415,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Erbauer vermeidet es, die Spirale ..., da eine einzige Berührung typischerweise eine Kettenreaktion auslöst.'::text,'zu berühren'::text,'zu berühren'::text,'berühren'::text,'Der Erbauer vermeidet es, die Spirale zu berühren, da eine einzige Berührung typischerweise eine Kettenreaktion auslöst.'::text),
(390733,43415,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Будівельник уникає ... спіралі, оскільки один дотик зазвичай спричиняє ланцюгову реакцію.'::text,'торкатися'::text,'торкнутися'::text,'торкнутися'::text,'Будівельник уникає торкатися спіралі, оскільки один дотик зазвичай спричиняє ланцюгову реакцію.'::text),
(390732,43415,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El constructor evita ... la espiral, ya que un solo toque suele provocar una reacción en cadena.'::text,'tocar'::text,'tocar'::text,'tocar'::text,'El constructor evita tocar la espiral, ya que un solo toque suele provocar una reacción en cadena.'::text),
(390731,43415,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le constructeur évite de ... la spirale, car un seul contact provoque typiquement une réaction en chaîne.'::text,'toucher'::text,'toucher'::text,'toucher'::text,'Le constructeur évite de toucher la spirale, car un seul contact provoque typiquement une réaction en chaîne.'::text),
(390734,43415,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yapan kişi spirale ... kaçınıyor, çünkü tek bir dokunuş tipik olarak zincirleme reaksiyona yol açar.'::text,'dokunmaktan'::text,'dokunmaktan'::text,'dokunmak'::text,'Yapan kişi spirale dokunmaktan kaçınıyor, çünkü tek bir dokunuş tipik olarak zincirleme reaksiyona yol açar.'::text),
(390735,43415,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az építő kerüli, hogy ... a spirálhoz, mivel egyetlen érintés jellemzően láncreakciót vált ki.'::text,'hozzáérjen'::text,'hozzáérjen'::text,'hozzáérjen'::text,'Az építő kerüli, hogy hozzáérjen a spirálhoz, mivel egyetlen érintés jellemzően láncreakciót vált ki.'::text),
(390738,43416,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ..., die du gebaut hast, ist das Coolste in dieser Halle.'::text,'die Spirale'::text,'eine Spirale'::text,'Spirale'::text,'Ehrlich, die Spirale, die du gebaut hast, ist das Coolste in dieser Halle.'::text),
(390742,43416,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ..., яку ти збудував, — найкрутіша річ у цій залі.'::text,'спіраль'::text,'спіраль'::text,'спіраль'::text,'Чесно, спіраль, яку ти збудував, — найкрутіша річ у цій залі.'::text),
(390741,43416,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... que construiste es lo más guapo de este pabellón.'::text,'la espiral'::text,'una espiral'::text,'espiral'::text,'La verdad, la espiral que construiste es lo más guapo de este pabellón.'::text),
(390740,43416,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ... que tu as construite est le truc le plus cool de cette salle.'::text,'la spirale'::text,'une spirale'::text,'spirale'::text,'Franchement, la spirale que tu as construite est le truc le plus cool de cette salle.'::text),
(390743,43416,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası yaptığın ... bu salondaki en havalı şey.'::text,'spiral'::text,'bir spiral'::text,'spiral'::text,'Açıkçası yaptığın spiral bu salondaki en havalı şey.'::text),
(390744,43416,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ..., amit építettél, a legmenőbb dolog ebben a csarnokban.'::text,'a spirál'::text,'egy spirál'::text,'spirál'::text,'Őszintén, a spirál, amit építettél, a legmenőbb dolog ebben a csarnokban.'::text),
(336558,37396,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um genau diese Zeit ... sie sich diese Blasenexplosion wieder an, total süchtig!'::text,'schaut gerade'::text,'schaut'::text,'schaut'::text,'Morgen um genau diese Zeit schaut gerade sie sich diese Blasenexplosion wieder an, total süchtig!'::text),
(336562,37396,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра саме в цей момент вона знову ... на той вибух бульбашок, повністю залипла!'::text,'дивитиметься'::text,'подивиться'::text,'дивиться'::text,'Завтра саме в цей момент вона знову дивитиметься на той вибух бульбашок, повністю залипла!'::text),
(336561,37396,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta misma hora, ... otra vez esa explosión de burbujas, totalmente enganchada!'::text,'estará viendo'::text,'verá'::text,'ve'::text,'¡Mañana a esta misma hora, estará viendo otra vez esa explosión de burbujas, totalmente enganchada!'::text),
(336560,37396,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cet instant précis, elle ... encore cette explosion de bulles, complètement accro !'::text,'sera en train de regarder'::text,'regardera'::text,'regarde'::text,'Demain à cet instant précis, elle sera en train de regarder encore cette explosion de bulles, complètement accro !'::text),
(336563,37396,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın tam bu anda o baloncuk patlamasını yine ..., resmen bağımlı!'::text,'izliyor olacak'::text,'izleyecek'::text,'izler'::text,'Yarın tam bu anda o baloncuk patlamasını yine izliyor olacak, resmen bağımlı!'::text),
(336564,37396,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap pontosan ebben a pillanatban megint ... azt a buborékrobbanást, teljesen rákattant!'::text,'nézni fogja'::text,'megnézi'::text,'nézi'::text,'Holnap pontosan ebben a pillanatban megint nézni fogja azt a buborékrobbanást, teljesen rákattant!'::text),
(336567,37397,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich verspreche, ... einen Block hineinzuwerfen. Diese Blasen waren eine totale Katastrophe!'::text,'nie wieder'::text,'nie wieder'::text,'nie'::text,'Ich verspreche, nie wieder einen Block hineinzuwerfen. Diese Blasen waren eine totale Katastrophe!'::text),
(336571,37397,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обіцяю, що ... ще один блок. Ті бульбашки були повною катастрофою!'::text,'більше ніколи не кину'::text,'більше ніколи не кидатиму'::text,'ніколи не кидаю'::text,'Обіцяю, що більше ніколи не кину ще один блок. Ті бульбашки були повною катастрофою!'::text),
(336570,37397,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prometo que nunca ... otro bloque. ¡Esas burbujas fueron un desastre total!'::text,'echaré'::text,'estaré echando'::text,'echo'::text,'Prometo que nunca echaré otro bloque. ¡Esas burbujas fueron un desastre total!'::text),
(336569,37397,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je promets que je ne ... plus jamais un bloc. Ces bulles étaient une catastrophe totale !'::text,'lâcherai'::text,'serai en train de lâcher'::text,'lâche'::text,'Je promets que je ne lâcherai plus jamais un bloc. Ces bulles étaient une catastrophe totale !'::text),
(336572,37397,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir daha asla başka blok ..., söz veriyorum. O baloncuklar tam bir felaketti!'::text,'atmayacağım'::text,'atıyor olmayacağım'::text,'atmam'::text,'Bir daha asla başka blok atmayacağım, söz veriyorum. O baloncuklar tam bir felaketti!'::text),
(336573,37397,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígérem, hogy soha többé ... bele blokkot. Azok a buborékok totális katasztrófa voltak!'::text,'nem dobok'::text,'nem fogok dobni'::text,'nem dobok'::text,'Megígérem, hogy soha többé nem dobok bele blokkot. Azok a buborékok totális katasztrófa voltak!'::text),
(336576,37398,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Tablette ins Wasser ..., steigen Bläschen nach oben.'::text,'fällt'::text,'fiel'::text,'fallen wird'::text,'Wenn eine Tablette ins Wasser fällt, steigen Bläschen nach oben.'::text),
(336580,37398,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо таблетка ... у воду, бульбашки піднімаються вгору.'::text,'падає'::text,'впала'::text,'впаде'::text,'Якщо таблетка падає у воду, бульбашки піднімаються вгору.'::text),
(336579,37398,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si una pastilla ... al agua, las burbujas suben.'::text,'cae'::text,'cayó'::text,'caerá'::text,'Si una pastilla cae al agua, las burbujas suben.'::text),
(336578,37398,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un comprimé ... dans l''eau, des bulles remontent à la surface.'::text,'tombe'::text,'est tombé'::text,'tombera'::text,'Si un comprimé tombe dans l''eau, des bulles remontent à la surface.'::text),
(336581,37398,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir tablet suya ..., kabarcıklar yukarı çıkar.'::text,'düşerse'::text,'düştüyse'::text,'düşecekse'::text,'Bir tablet suya düşerse, kabarcıklar yukarı çıkar.'::text),
(336582,37398,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy tabletta a vízbe ..., buborékok szállnak fel.'::text,'esik'::text,'esett'::text,'esni fog'::text,'Ha egy tabletta a vízbe esik, buborékok szállnak fel.'::text),
(336585,37399,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor diesem Experiment ... sie, Blasen im Wasser seien langweilig.'::text,'dachte früher'::text,'dachte'::text,'war es gewohnt zu denken'::text,'Vor diesem Experiment dachte früher sie, Blasen im Wasser seien langweilig.'::text),
(336589,37399,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До цього експерименту вона ..., що бульбашки у воді нудні.'::text,'вважала'::text,'вважала'::text,'звикла вважати'::text,'До цього експерименту вона вважала, що бульбашки у воді нудні.'::text),
(336588,37399,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de este experimento, ... pensar que las burbujas en el agua eran aburridas.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Antes de este experimento, solía pensar que las burbujas en el agua eran aburridas.'::text),
(336587,37399,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant cette expérience, elle ... que les bulles dans l''eau étaient ennuyeuses.'::text,'pensait'::text,'pensait'::text,'était habituée à penser'::text,'Avant cette expérience, elle pensait que les bulles dans l''eau étaient ennuyeuses.'::text),
(336590,37399,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu deneyden önce sudaki kabarcıkların sıkıcı olduğunu ...'::text,'düşünürdü'::text,'düşünürdü'::text,'düşünmeye alışkındı'::text,'Bu deneyden önce sudaki kabarcıkların sıkıcı olduğunu düşünürdü.'::text),
(336591,37399,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'E kísérlet előtt ..., hogy a vízben lévő buborékok unalmasak.'::text,'régen azt gondolta'::text,'azt gondolta'::text,'megszokta gondolni'::text,'E kísérlet előtt régen azt gondolta, hogy a vízben lévő buborékok unalmasak.'::text),
(336594,37400,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das Glas weiter um, während die Blasen aufsteigen.'::text,'rührt'::text,'rührt'::text,'rührt'::text,'Sie rührt das Glas weiter um, während die Blasen aufsteigen.'::text),
(336598,37400,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона й далі ... склянку, поки бульбашки піднімаються.'::text,'помішує'::text,'помішує'::text,'помішує'::text,'Вона й далі помішує склянку, поки бульбашки піднімаються.'::text),
(336597,37400,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sigue ... el vaso mientras suben las burbujas.'::text,'removiendo'::text,'remover'::text,'remover'::text,'Sigue removiendo el vaso mientras suben las burbujas.'::text),
(336596,37400,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle continue de ... le verre pendant que les bulles remontent.'::text,'remuer'::text,'remuer'::text,'remuer'::text,'Elle continue de remuer le verre pendant que les bulles remontent.'::text),
(336599,37400,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kabarcıklar yükselirken bardağı ... devam ediyor.'::text,'karıştırmaya'::text,'karıştırmaya'::text,'karıştırmak'::text,'Kabarcıklar yükselirken bardağı karıştırmaya devam ediyor.'::text),
(336600,37400,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tovább ... a poharat, miközben szállnak fel a buborékok.'::text,'kavarja'::text,'kavarja'::text,'kavarja'::text,'Tovább kavarja a poharat, miközben szállnak fel a buborékok.'::text),
(336612,37402,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich lüg nicht, du hast bei den Blasen nach Luft geschnappt – und ... ich!'::text,'genauso'::text,'genauso'::text,'ebenso wenig'::text,'Ich lüg nicht, du hast bei den Blasen nach Luft geschnappt – und genauso ich!'::text),
(336616,37402,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ахнула від тих бульбашок, і ... я.'::text,'так само'::text,'так само'::text,'ні'::text,'Не буду брехати, ти ахнула від тих бульбашок, і так само я.'::text),
(336615,37402,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, te quedaste sin aliento con esas burbujas, y ... yo.'::text,'también'::text,'también'::text,'tampoco'::text,'No voy a mentir, te quedaste sin aliento con esas burbujas, y también yo.'::text),
(336614,37402,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, t''as eu le souffle coupé devant ces bulles, et ... moi.'::text,'pareil pour'::text,'pareil pour'::text,'pas pour'::text,'Je vais pas mentir, t''as eu le souffle coupé devant ces bulles, et pareil pour moi.'::text),
(336617,37402,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o kabarcıklar karşısında nefesin kesildi, ... benim de.'::text,'aynen'::text,'aynen'::text,'ne de'::text,'Yalan yok, o kabarcıklar karşısında nefesin kesildi, aynen benim de.'::text),
(336618,37402,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, elakadt a lélegzeted azoktól a buborékoktól, és ... nekem.'::text,'ugyanígy'::text,'ugyanígy'::text,'ugyanígy nem'::text,'Nem hazudok, elakadt a lélegzeted azoktól a buborékoktól, és ugyanígy nekem.'::text),
(336630,37404,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte sie einen kleineren Block benutzt, ... die Blasen nicht den ganzen Tank gefüllt. Eindeutig ein sanfter Test.'::text,'hätten'::text,'werden'::text,'haben'::text,'Hätte sie einen kleineren Block benutzt, hätten die Blasen nicht den ganzen Tank gefüllt. Eindeutig ein sanfter Test.'::text),
(336634,37404,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона взяла менший блок, бульбашки ... весь резервуар. Очевидно, лагідний тест.'::text,'не заповнили б'::text,'не заповнять'::text,'не заповнили'::text,'Якби вона взяла менший блок, бульбашки не заповнили б весь резервуар. Очевидно, лагідний тест.'::text),
(336633,37404,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera usado un bloque más pequeño, las burbujas no ... todo el tanque. Claramente una prueba suave.'::text,'habrían llenado'::text,'llenarán'::text,'llenaron'::text,'Si hubiera usado un bloque más pequeño, las burbujas no habrían llenado todo el tanque. Claramente una prueba suave.'::text),
(336632,37404,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle avait utilisé un bloc plus petit, les bulles ... tout l''aquarium. Clairement un test tout en douceur.'::text,'n''auraient pas rempli'::text,'ne rempliront pas'::text,'n''ont pas rempli'::text,'Si elle avait utilisé un bloc plus petit, les bulles n''auraient pas rempli tout l''aquarium. Clairement un test tout en douceur.'::text),
(336635,37404,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha küçük bir blok kullansaydı, kabarcıklar bütün tankı ..., belli ki nazik bir testti.'::text,'doldurmazdı'::text,'doldurmayacak'::text,'doldurmadı'::text,'Daha küçük bir blok kullansaydı, kabarcıklar bütün tankı doldurmazdı, belli ki nazik bir testti.'::text),
(336636,37404,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kisebb blokkot használt volna, a buborékok ... az egész tartályt. Nyilván egy gyengéd teszt.'::text,'nem töltötték volna meg'::text,'nem töltik meg'::text,'nem töltötték meg'::text,'Ha kisebb blokkot használt volna, a buborékok nem töltötték volna meg az egész tartályt. Nyilván egy gyengéd teszt.'::text),
(336639,37405,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie bestritt, den größten Block absichtlich ..., die Blasen waren eindeutig ein Unfall.'::text,'hineingeworfen zu haben'::text,'hineinzuwerfen'::text,'hineingeworfen'::text,'Sie bestritt, den größten Block absichtlich hineingeworfen zu haben, die Blasen waren eindeutig ein Unfall.'::text),
(336643,37405,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона заперечила, що ... найбільший блок навмисно. Бульбашки були явно випадковістю.'::text,'кинула'::text,'кинути'::text,'кинутий'::text,'Вона заперечила, що кинула найбільший блок навмисно. Бульбашки були явно випадковістю.'::text),
(336642,37405,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negó ... el bloque más grande a propósito. Las burbujas fueron claramente un accidente.'::text,'haber echado'::text,'echar'::text,'echado'::text,'Negó haber echado el bloque más grande a propósito. Las burbujas fueron claramente un accidente.'::text),
(336641,37405,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a nié ... le plus gros bloc exprès. Les bulles étaient clairement un accident.'::text,'avoir lâché'::text,'lâcher'::text,'lâché'::text,'Elle a nié avoir lâché le plus gros bloc exprès. Les bulles étaient clairement un accident.'::text),
(336644,37405,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En büyük bloğu bilerek ... inkâr etti. Kabarcıklar belli ki bir kazaydı.'::text,'attığını'::text,'atmayı'::text,'atılmış'::text,'En büyük bloğu bilerek attığını inkâr etti. Kabarcıklar belli ki bir kazaydı.'::text),
(336645,37405,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy szándékosan ... bele a legnagyobb blokkot. A buborékok nyilván balesetek voltak.'::text,'dobta'::text,'dobni'::text,'dobott'::text,'Tagadta, hogy szándékosan dobta bele a legnagyobb blokkot. A buborékok nyilván balesetek voltak.'::text),
(336648,37406,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor der Tank weiß wurde, ... die Blasen eine Minute lang aufgestiegen. Leicht dramatisch.'::text,'waren'::text,'sind'::text,'steigen'::text,'Bevor der Tank weiß wurde, waren die Blasen eine Minute lang aufgestiegen. Leicht dramatisch.'::text),
(336652,37406,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж резервуар побілів, бульбашки ... цілу хвилину. Трішки драматично.'::text,'піднімалися'::text,'піднімаються'::text,'піднімаються'::text,'Перш ніж резервуар побілів, бульбашки піднімалися цілу хвилину. Трішки драматично.'::text),
(336651,37406,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que el tanque se volviera blanco, las burbujas ... subiendo un minuto. Un pelín dramático.'::text,'habían estado'::text,'han estado'::text,'están'::text,'Antes de que el tanque se volviera blanco, las burbujas habían estado subiendo un minuto. Un pelín dramático.'::text),
(336650,37406,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant que l''aquarium devienne blanc, les bulles ... depuis une minute. Un poil dramatique.'::text,'montaient'::text,'montent'::text,'montent'::text,'Avant que l''aquarium devienne blanc, les bulles montaient depuis une minute. Un poil dramatique.'::text),
(336653,37406,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tank beyazlamadan önce kabarcıklar bir dakika boyunca ..., azıcık dramatik.'::text,'yükselmişti'::text,'yükseliyor'::text,'yükselir'::text,'Tank beyazlamadan önce kabarcıklar bir dakika boyunca yükselmişti, azıcık dramatik.'::text),
(336654,37406,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a tartály kifehéredett, a buborékok egy percen át ... felfelé. Kicsit drámai.'::text,'szálltak'::text,'szállnak'::text,'szállnak'::text,'Mielőtt a tartály kifehéredett, a buborékok egy percen át szálltak felfelé. Kicsit drámai.'::text),
(365160,40574,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er den Sonnenuntergang durch sein Objektiv ..., wurde es dunkel. Tolles Timing, klar.'::text,'filmte'::text,'filmte'::text,'gefilmt hat'::text,'Während er den Sonnenuntergang durch sein Objektiv filmte, wurde es dunkel. Tolles Timing, klar.'::text),
(365164,40574,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ... захід сонця через об''єктив, стемніло. Чудовий таймінг, звісно.'::text,'знімав'::text,'зняв'::text,'зняв'::text,'Поки він знімав захід сонця через об''єктив, стемніло. Чудовий таймінг, звісно.'::text),
(365163,40574,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... la puesta de sol con su objetivo, se hizo de noche. Qué buen momento, obviamente.'::text,'grababa'::text,'grabó'::text,'ha grabado'::text,'Mientras grababa la puesta de sol con su objetivo, se hizo de noche. Qué buen momento, obviamente.'::text),
(365162,40574,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ... le coucher du soleil à travers son objectif, il a fait nuit. Timing parfait, évidemment.'::text,'filmait'::text,'a filmé'::text,'a filmé'::text,'Pendant qu''il filmait le coucher du soleil à travers son objectif, il a fait nuit. Timing parfait, évidemment.'::text),
(365165,40574,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O gün batımını objektifinden ..., hava karardı. Harika zamanlama, tabii.'::text,'çekerken'::text,'çekti'::text,'çekmiş'::text,'O gün batımını objektifinden çekerken, hava karardı. Harika zamanlama, tabii.'::text),
(365166,40574,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a naplementét ... az objektívén át, besötétedett. Remek időzítés, persze.'::text,'filmezte'::text,'lefilmezte'::text,'lefilmezte'::text,'Miközben a naplementét filmezte az objektívén át, besötétedett. Remek időzítés, persze.'::text),
(365169,40575,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit fünf Stunden durch dieses lange Objektiv, und seine Knie sind komplett hinüber!'::text,'schaut'::text,'schaut gerade'::text,'schaut'::text,'Er schaut seit fünf Stunden durch dieses lange Objektiv, und seine Knie sind komplett hinüber!'::text),
(365173,40575,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... крізь той довгий об''єктив уже п''ять годин, і його коліна повністю вбиті!'::text,'дивиться'::text,'дивиться'::text,'дивиться'::text,'Він дивиться крізь той довгий об''єктив уже п''ять годин, і його коліна повністю вбиті!'::text),
(365172,40575,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... por ese objetivo largo durante cinco horas y tiene las rodillas destrozadas!'::text,'Ha estado mirando'::text,'Está mirando'::text,'Mira'::text,'¡Ha estado mirando por ese objetivo largo durante cinco horas y tiene las rodillas destrozadas!'::text),
(365171,40575,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... à travers ce long objectif depuis cinq heures, et ses genoux sont complètement détruits !'::text,'regarde'::text,'regarde'::text,'regarde'::text,'Il regarde à travers ce long objectif depuis cinq heures, et ses genoux sont complètement détruits !'::text),
(365174,40575,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beş saattir o uzun objektiften ... ve dizleri tamamen mahvoldu!'::text,'bakıyor'::text,'bakıyor'::text,'bakar'::text,'Beş saattir o uzun objektiften bakıyor ve dizleri tamamen mahvoldu!'::text),
(365175,40575,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öt órája ... abba a hosszú objektívbe, és a térde teljesen tönkrement!'::text,'néz'::text,'néz'::text,'néz'::text,'Öt órája néz abba a hosszú objektívbe, és a térde teljesen tönkrement!'::text),
(365178,40576,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade die Rose durch sein Objektiv, als ein Vogel ins Bild krachte. Katastrophe!'::text,'fotografierte'::text,'fotografierte'::text,'hat fotografiert'::text,'Er fotografierte gerade die Rose durch sein Objektiv, als ein Vogel ins Bild krachte. Katastrophe!'::text),
(365182,40576,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... троянду крізь об''єктив, коли в кадр врізався птах. Катастрофа!'::text,'фотографував'::text,'сфотографував'::text,'сфотографував'::text,'Він фотографував троянду крізь об''єктив, коли в кадр врізався птах. Катастрофа!'::text),
(365181,40576,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la rosa con su objetivo cuando un pájaro se estampó contra el plano. ¡Desastre!'::text,'Estaba fotografiando'::text,'Fotografió'::text,'Ha fotografiado'::text,'Estaba fotografiando la rosa con su objetivo cuando un pájaro se estampó contra el plano. ¡Desastre!'::text),
(365180,40576,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la rose à travers son objectif quand un oiseau s''est écrasé dans le cadre. Catastrophe !'::text,'photographiait'::text,'a photographié'::text,'a photographié'::text,'Il photographiait la rose à travers son objectif quand un oiseau s''est écrasé dans le cadre. Catastrophe !'::text),
(365183,40576,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, objektifinden gülün fotoğrafını ..., derken kadraja bir kuş çarptı. Felaket!'::text,'çekiyordu'::text,'çekti'::text,'çekti'::text,'O, objektifinden gülün fotoğrafını çekiyordu, derken kadraja bir kuş çarptı. Felaket!'::text),
(365184,40576,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a rózsát az objektívén át, amikor egy madár becsapódott a képbe. Katasztrófa!'::text,'fotózta'::text,'lefotózta'::text,'lefotózta'::text,'Épp fotózta a rózsát az objektívén át, amikor egy madár becsapódott a képbe. Katasztrófa!'::text),
(365187,40577,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, er ... angeblich heute schon dreimal sein Objektiv geputzt.'::text,'hat'::text,'hat'::text,'putzt'::text,'Warte, er hat angeblich heute schon dreimal sein Objektiv geputzt.'::text),
(365191,40577,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, він, кажуть, сьогодні вже тричі ... об''єктив.'::text,'почистив'::text,'чистив'::text,'чистить'::text,'Стривай, він, кажуть, сьогодні вже тричі почистив об''єктив.'::text),
(365190,40577,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, al parecer hoy ya ... el objetivo tres veces.'::text,'ha limpiado'::text,'ha estado limpiando'::text,'está limpiando'::text,'Espera, al parecer hoy ya ha limpiado el objetivo tres veces.'::text),
(365189,40577,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment il ... déjà son objectif trois fois aujourd''hui.'::text,'a nettoyé'::text,'a nettoyé'::text,'nettoie'::text,'Attends, apparemment il a nettoyé déjà son objectif trois fois aujourd''hui.'::text),
(365192,40577,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, güya bugün objektifini şimdiden üç kez ...'::text,'temizlemiş'::text,'temizliyormuş'::text,'temizliyor'::text,'Dur, güya bugün objektifini şimdiden üç kez temizlemiş.'::text),
(365193,40577,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag ma már háromszor ... az objektívét.'::text,'megtisztította'::text,'tisztogatta'::text,'tisztítja'::text,'Várj, állítólag ma már háromszor megtisztította az objektívét.'::text),
(365196,40578,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich hab gehört, er ... den Objektivdeckel vor dem roten Teppich zu Hause gelassen.'::text,'hatte'::text,'hat'::text,'lässt'::text,'Rate mal, ich hab gehört, er hatte den Objektivdeckel vor dem roten Teppich zu Hause gelassen.'::text),
(365200,40578,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вгадай що, я чула, що він ... кришку об''єктива вдома перед червоною доріжкою.'::text,'залишив'::text,'залишив'::text,'залишає'::text,'Вгадай що, я чула, що він залишив кришку об''єктива вдома перед червоною доріжкою.'::text),
(365199,40578,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, me han dicho que ... la tapa del objetivo en casa antes de la alfombra roja.'::text,'se había dejado'::text,'se ha dejado'::text,'se deja'::text,'Adivina qué, me han dicho que se había dejado la tapa del objetivo en casa antes de la alfombra roja.'::text),
(365198,40578,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, j''ai entendu qu''il ... le bouchon d''objectif à la maison avant le tapis rouge.'::text,'avait laissé'::text,'a laissé'::text,'laisse'::text,'Devine quoi, j''ai entendu qu''il avait laissé le bouchon d''objectif à la maison avant le tapis rouge.'::text),
(365201,40578,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, duyduğuma göre kırmızı halıdan önce objektif kapağını evde ...'::text,'bırakmış'::text,'bırakmış'::text,'bırakıyor'::text,'Bil bakalım ne oldu, duyduğuma göre kırmızı halıdan önce objektif kapağını evde bırakmış.'::text),
(365202,40578,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy a vörös szőnyeg előtt otthon ... az objektívsapkát.'::text,'hagyta'::text,'hagyta'::text,'hagyja'::text,'Képzeld, azt hallottam, hogy a vörös szőnyeg előtt otthon hagyta az objektívsapkát.'::text),
(365205,40579,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wenn das Objektiv einen Kratzer kriegt, ... er das ganze Shooting, echt.'::text,'verliert'::text,'verlöre'::text,'verlor'::text,'Yo, wenn das Objektiv einen Kratzer kriegt, verliert er das ganze Shooting, echt.'::text),
(365209,40579,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, якщо той об''єктив подряпається, він ... всю зйомку, чесно.'::text,'втратить'::text,'втратив би'::text,'втратив'::text,'Йо, якщо той об''єктив подряпається, він втратить всю зйомку, чесно.'::text),
(365208,40579,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, si ese objetivo se raya, ... toda la sesión, en serio.'::text,'perderá'::text,'perdería'::text,'perdió'::text,'Oye, si ese objetivo se raya, perderá toda la sesión, en serio.'::text),
(365207,40579,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, si cet objectif se raye, il ... tout le shooting, sérieux.'::text,'perdra'::text,'perdrait'::text,'a perdu'::text,'Yo, si cet objectif se raye, il perdra tout le shooting, sérieux.'::text),
(365210,40579,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, o objektif çizilirse bütün çekimi ..., cidden.'::text,'kaybedecek'::text,'kaybederdi'::text,'kaybetti'::text,'Yo, o objektif çizilirse bütün çekimi kaybedecek, cidden.'::text),
(365211,40579,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ha megkarcolódik az objektív, ... az egész fotózást, komolyan.'::text,'elbukja'::text,'elbukná'::text,'elbukta'::text,'Figyu, ha megkarcolódik az objektív, elbukja az egész fotózást, komolyan.'::text),
(365214,40580,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn ich so ein langes Objektiv hätte, ... ich Fotos vom Mond, kein Witz.'::text,'machte'::text,'mache'::text,'mache'::text,'Bro, wenn ich so ein langes Objektiv hätte, machte ich Fotos vom Mond, kein Witz.'::text),
(365218,40580,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби я мав такий довгий об''єктив, я ... фотки місяця, без жартів.'::text,'робив би'::text,'робитиму'::text,'роблю'::text,'Бро, якби я мав такий довгий об''єктив, я робив би фотки місяця, без жартів.'::text),
(365217,40580,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si tuviera un objetivo tan largo, ... fotos de la luna, en serio.'::text,'haría'::text,'haré'::text,'hago'::text,'Bro, si tuviera un objetivo tan largo, haría fotos de la luna, en serio.'::text),
(365216,40580,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si j''avais un objectif aussi long, je ... des photos de la lune, sans mentir.'::text,'prendrais'::text,'prendrai'::text,'prends'::text,'Frérot, si j''avais un objectif aussi long, je prendrais des photos de la lune, sans mentir.'::text),
(365219,40580,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o kadar uzun objektifim olsa ayın fotoğraflarını ..., yalan yok.'::text,'çekerdim'::text,'çekeceğim'::text,'çekerim'::text,'Kanka, o kadar uzun objektifim olsa ayın fotoğraflarını çekerdim, yalan yok.'::text),
(365220,40580,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha ilyen hosszú objektívem lenne, ... a Holdat, komolyan.'::text,'fotóznám'::text,'fotózni fogom'::text,'fotózom'::text,'Tesó, ha ilyen hosszú objektívem lenne, fotóznám a Holdat, komolyan.'::text),
(365232,40582,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei Sonnenuntergang ... der Fotograf seine Kamera samt Objektiv auf ein Stativ.'::text,'stellte'::text,'wurde gestellt'::text,'stellend'::text,'Bei Sonnenuntergang stellte der Fotograf seine Kamera samt Objektiv auf ein Stativ.'::text),
(365236,40582,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На заході сонця фотограф ... камеру й об''єктив на штатив.'::text,'поставив'::text,'був поставлений'::text,'ставлення'::text,'На заході сонця фотограф поставив камеру й об''єктив на штатив.'::text),
(365235,40582,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al atardecer, el fotógrafo ... la cámara y el objetivo en un trípode.'::text,'colocó'::text,'fue colocado'::text,'colocando'::text,'Al atardecer, el fotógrafo colocó la cámara y el objetivo en un trípode.'::text),
(365234,40582,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au coucher du soleil, le photographe ... son appareil et son objectif sur un trépied.'::text,'a placé'::text,'a été placé'::text,'plaçant'::text,'Au coucher du soleil, le photographe a placé son appareil et son objectif sur un trépied.'::text),
(365237,40582,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımında fotoğrafçı fotoğraf makinesini ve objektifini tripoda ...'::text,'yerleştirdi'::text,'yerleştirildi'::text,'yerleştirme'::text,'Gün batımında fotoğrafçı fotoğraf makinesini ve objektifini tripoda yerleştirdi.'::text),
