(365241,40583,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fotos sehen sehr scharf aus, also ... das Objektiv ein gutes sein.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Die Fotos sehen sehr scharf aus, also muss das Objektiv ein gutes sein.'::text),
(365245,40583,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фото дуже чіткі, тож об''єктив ... бути хорошим.'::text,'має'::text,'не може'::text,'не повинен'::text,'Фото дуже чіткі, тож об''єктив має бути хорошим.'::text),
(365244,40583,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las fotos se ven muy nítidas, así que el objetivo ... ser bueno.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Las fotos se ven muy nítidas, así que el objetivo debe de ser bueno.'::text),
(365243,40583,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les photos sont très nettes, donc l''objectif ... être bon.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Les photos sont très nettes, donc l''objectif doit être bon.'::text),
(365246,40583,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fotoğraflar çok net görünüyor, yani objektif iyi ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Fotoğraflar çok net görünüyor, yani objektif iyi olmalı.'::text),
(365247,40583,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fotók nagyon élesek, tehát az objektív ... jó.'::text,'biztos'::text,'nem lehet'::text,'nem szabad'::text,'A fotók nagyon élesek, tehát az objektív biztos jó.'::text),
(349302,38812,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Crew ... den ganzen Vormittag auf die Drohnenaufnahme. Eindeutig ein schneller Job.'::text,'wartet'::text,'wartet gerade'::text,'wartet'::text,'Die Crew wartet den ganzen Vormittag auf die Drohnenaufnahme. Eindeutig ein schneller Job.'::text),
(349306,38812,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Знімальна група ... на кадр із дрона весь ранок. Явно швидка робота.'::text,'чекає'::text,'чекає'::text,'чекає'::text,'Знімальна група чекає на кадр із дрона весь ранок. Явно швидка робота.'::text),
