(349307,38812,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip sabahtan beri drone çekimi için ..., belli ki hızlı bir iş.'::text,'bekliyor'::text,'bekliyor'::text,'bekler'::text,'Ekip sabahtan beri drone çekimi için bekliyor, belli ki hızlı bir iş.'::text),
