(349315,38813,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дрон ... над полем, коли трава прилягла. Оце так несподіванка.'::text,'зависав'::text,'завис'::text,'завис'::text,'Дрон зависав над полем, коли трава прилягла. Оце так несподіванка.'::text),
