(349316,38813,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Drone tarlanın üzerinde ..., derken çimler yere yattı. Ne sürpriz ama.'::text,'asılı duruyordu'::text,'asılı durdu'::text,'asılı durdu'::text,'Drone tarlanın üzerinde asılı duruyordu, derken çimler yere yattı. Ne sürpriz ama.'::text),
