(349324,38814,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, цей дрон сьогодні ... десь над десятьма полями, без жартів.'::text,'пролетів'::text,'літав'::text,'пролетів'::text,'Бро, цей дрон сьогодні пролетів десь над десятьма полями, без жартів.'::text),
