(349379,38820,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Drone, güçlü rüzgâra ... tarım arazisinin üzerinde uçmaya devam ediyor.'::text,'rağmen'::text,'rağmen'::text,'olmadıkça'::text,'Drone, güçlü rüzgâra rağmen tarım arazisinin üzerinde uçmaya devam ediyor.'::text),
(349380,38820,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A drón az erős szél ... tovább repül a termőföld fölött.'::text,'ellenére'::text,'bár'::text,'hacsak nem'::text,'A drón az erős szél ellenére tovább repül a termőföld fölött.'::text),
(349383,38821,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, bis nächstes Jahr ... du dein eigenes Drohnen-Filmstudio eröffnet.'::text,'hast'::text,'wirst'::text,'eröffnest'::text,'Respekt, bis nächstes Jahr hast du dein eigenes Drohnen-Filmstudio eröffnet.'::text),
(349387,38821,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, до наступного року ти ... власну кіностудію з дронами.'::text,'відкриєш'::text,'відкриєш'::text,'відкриваєш'::text,'Респект, до наступного року ти відкриєш власну кіностудію з дронами.'::text),
(349386,38821,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, para el año que viene ... tu propio estudio de cine con drones.'::text,'habrás abierto'::text,'abrirás'::text,'abres'::text,'Respeto, para el año que viene habrás abierto tu propio estudio de cine con drones.'::text),
(349385,38821,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, d''ici l''année prochaine, tu ... ton propre studio de films au drone.'::text,'auras ouvert'::text,'ouvriras'::text,'ouvres'::text,'Respect, d''ici l''année prochaine, tu auras ouvert ton propre studio de films au drone.'::text),
(349388,38821,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar, seneye kadar kendi drone film stüdyonu ...'::text,'açmış olacaksın'::text,'açacaksın'::text,'açarsın'::text,'Saygılar, seneye kadar kendi drone film stüdyonu açmış olacaksın.'::text),
(349389,38821,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, jövő évre ... a saját drónos filmstúdiódat.'::text,'megnyitod'::text,'megnyitod'::text,'nyitod'::text,'Respekt, jövő évre megnyitod a saját drónos filmstúdiódat.'::text),
(396525,44059,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie wieder beide Daumen hoch. So eine seltene Stimmung, klar.'::text,'hält gerade'::text,'hält'::text,'hält'::text,'Morgen um diese Zeit hält gerade sie wieder beide Daumen hoch. So eine seltene Stimmung, klar.'::text),
(396529,44059,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона знову ... обидва великі пальці вгору. Такий рідкісний настрій, звісно.'::text,'триматиме'::text,'підніме'::text,'тримає'::text,'Завтра в цей час вона знову триматиме обидва великі пальці вгору. Такий рідкісний настрій, звісно.'::text),
(396528,44059,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, ... otra vez los dos pulgares arriba. Qué estado de ánimo tan raro, obviamente.'::text,'estará poniendo'::text,'pondrá'::text,'pone'::text,'Mañana a esta hora, estará poniendo otra vez los dos pulgares arriba. Qué estado de ánimo tan raro, obviamente.'::text),
(396527,44059,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... encore les deux pouces en l''air. Une humeur si rare, évidemment.'::text,'sera en train de lever'::text,'lèvera'::text,'lève'::text,'Demain à la même heure, elle sera en train de lever encore les deux pouces en l''air. Une humeur si rare, évidemment.'::text),
(396530,44059,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde yine iki başparmağını da havaya ..., ne kadar nadir bir ruh hali, tabii.'::text,'kaldırıyor olacak'::text,'kaldıracak'::text,'kaldırır'::text,'Yarın bu saatlerde yine iki başparmağını da havaya kaldırıyor olacak, ne kadar nadir bir ruh hali, tabii.'::text),
(396531,44059,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint ... mindkét hüvelykujját. Micsoda ritka hangulat, persze.'::text,'fogja feltartani'::text,'feltartja'::text,'feltartja'::text,'Holnap ilyenkor megint fogja feltartani mindkét hüvelykujját. Micsoda ritka hangulat, persze.'::text),
(396534,44060,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ich wette, sie ... auch im nächsten Video zwei Daumen hoch, echt.'::text,'zeigt'::text,'zeigt'::text,'zeigt'::text,'Bro, ich wette, sie zeigt auch im nächsten Video zwei Daumen hoch, echt.'::text),
(396538,44060,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, б''юся об заклад, що в наступному відео вона теж ... два пальці вгору, чесно.'::text,'покаже'::text,'показуватиме'::text,'показує'::text,'Бро, б''юся об заклад, що в наступному відео вона теж покаже два пальці вгору, чесно.'::text),
(396537,44060,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, apuesto a que en su próximo vídeo también ... los dos pulgares arriba, en serio.'::text,'pondrá'::text,'estará poniendo'::text,'pone'::text,'Bro, apuesto a que en su próximo vídeo también pondrá los dos pulgares arriba, en serio.'::text),
(396536,44060,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, je parie qu''elle ... aussi deux pouces levés dans sa prochaine vidéo, sérieux.'::text,'fera'::text,'fera'::text,'fait'::text,'Frérot, je parie qu''elle fera aussi deux pouces levés dans sa prochaine vidéo, sérieux.'::text),
(396539,44060,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bahse girerim bir sonraki videosunda da iki başparmak ..., cidden.'::text,'kaldıracak'::text,'kaldırıyor olacak'::text,'kaldırır'::text,'Kanka, bahse girerim bir sonraki videosunda da iki başparmak kaldıracak, cidden.'::text),
(396540,44060,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, fogadok, hogy a következő videójában is ... mindkét hüvelykujját, komolyan.'::text,'felmutatja'::text,'fel fogja mutatni'::text,'felmutatja'::text,'Tesó, fogadok, hogy a következő videójában is felmutatja mindkét hüvelykujját, komolyan.'::text),
(396543,44061,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, wenn ein Video knallt, ... sie beide Daumen hoch, kein Witz.'::text,'zeigt'::text,'zeigt'::text,'zeigte'::text,'Alter, wenn ein Video knallt, zeigt sie beide Daumen hoch, kein Witz.'::text),
(396547,44061,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якщо відео качає, вона ... обидва пальці вгору, без жартів.'::text,'показує'::text,'покаже'::text,'показала'::text,'Чувак, якщо відео качає, вона показує обидва пальці вгору, без жартів.'::text),
(396546,44061,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si un vídeo mola, ... los dos pulgares arriba, en serio.'::text,'pone'::text,'pondrá'::text,'puso'::text,'Tío, si un vídeo mola, pone los dos pulgares arriba, en serio.'::text),
(396545,44061,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, si une vidéo déchire, elle ... les deux pouces, sans mentir.'::text,'lève'::text,'lèvera'::text,'a levé'::text,'Mec, si une vidéo déchire, elle lève les deux pouces, sans mentir.'::text),
(396548,44061,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, video bomba gibiyse iki başparmağını da ..., yalan yok.'::text,'kaldırır'::text,'kaldıracak'::text,'kaldırdı'::text,'Kanka, video bomba gibiyse iki başparmağını da kaldırır, yalan yok.'::text),
(396549,44061,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha egy videó ütős, ... mindkét hüvelykujját, komolyan.'::text,'felmutatja'::text,'fel fogja mutatni'::text,'felmutatta'::text,'Tesó, ha egy videó ütős, felmutatja mindkét hüvelykujját, komolyan.'::text),
(396552,44062,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hält beide Daumen hoch vors Objektiv, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Sie hält beide Daumen hoch vors Objektiv, oder?'::text),
(396556,44062,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона тримає обидва великі пальці вгору до об''єктива, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Вона тримає обидва великі пальці вгору до об''єктива, так?'::text),
(396555,44062,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pone los dos pulgares arriba hacia el objetivo, ...?'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Pone los dos pulgares arriba hacia el objetivo, ¿verdad?'::text),
(396554,44062,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle lève les deux pouces vers l''objectif, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Elle lève les deux pouces vers l''objectif, non ?'::text),
(396557,44062,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki başparmağını da objektife doğru havaya kaldırıyor, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil miydi?'::text,'İki başparmağını da objektife doğru havaya kaldırıyor, değil mi?'::text),
(396558,44062,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindkét hüvelykujját feltartja az objektív felé, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Mindkét hüvelykujját feltartja az objektív felé, ugye?'::text),
(396570,44064,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Montage ... das Mädchen beide Daumen gehoben, was typischerweise Zustimmung signalisiert.'::text,'hat'::text,'wird'::text,'hebt'::text,'Bis zum Ende der Montage hat das Mädchen beide Daumen gehoben, was typischerweise Zustimmung signalisiert.'::text),
(396574,44064,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця монтажу дівчина ... обидва великі пальці, що зазвичай означає схвалення.'::text,'підніме'::text,'підніме'::text,'підніматиме'::text,'До кінця монтажу дівчина підніме обидва великі пальці, що зазвичай означає схвалення.'::text),
(396573,44064,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al final del montaje, la chica ... los dos pulgares, lo que típicamente indica aprobación.'::text,'habrá levantado'::text,'levantará'::text,'estará levantando'::text,'Al final del montaje, la chica habrá levantado los dos pulgares, lo que típicamente indica aprobación.'::text),
(396572,44064,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du montage, la fille ... les deux pouces, ce qui indique typiquement l''approbation.'::text,'aura levé'::text,'lèvera'::text,'sera en train de lever'::text,'D''ici la fin du montage, la fille aura levé les deux pouces, ce qui indique typiquement l''approbation.'::text),
(396575,44064,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Montajın sonuna kadar kız iki başparmağını da ..., bu da tipik olarak onay anlamına gelir.'::text,'kaldırmış olacak'::text,'kaldıracak'::text,'kaldırıyor olacak'::text,'Montajın sonuna kadar kız iki başparmağını da kaldırmış olacak, bu da tipik olarak onay anlamına gelir.'::text),
(396576,44064,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A montázs végére a lány ... mindkét hüvelykujját, ami jellemzően egyetértést jelez.'::text,'felemeli'::text,'felemeli'::text,'emelni fogja'::text,'A montázs végére a lány felemeli mindkét hüvelykujját, ami jellemzően egyetértést jelez.'::text),
(396579,44065,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Daumen nicht gehoben hätte, ... das Video nicht so freundlich ausgesehen.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn sie die Daumen nicht gehoben hätte, hätte das Video nicht so freundlich ausgesehen.'::text),
(396583,44065,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не підняла пальці, відео ... так дружньо.'::text,'не виглядало б'::text,'не виглядатиме'::text,'не виглядало'::text,'Якби вона не підняла пальці, відео не виглядало б так дружньо.'::text),
(396582,44065,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera levantado los pulgares, el vídeo no ... tan simpático.'::text,'habría parecido'::text,'parecerá'::text,'pareció'::text,'Si no hubiera levantado los pulgares, el vídeo no habría parecido tan simpático.'::text),
(396581,44065,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas levé les pouces, la vidéo ... aussi sympa.'::text,'n''aurait pas eu l''air'::text,'n''aura pas l''air'::text,'n''a pas eu l''air'::text,'Si elle n''avait pas levé les pouces, la vidéo n''aurait pas eu l''air aussi sympa.'::text),
(396584,44065,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başparmaklarını kaldırmasaydı video bu kadar samimi ...'::text,'görünmezdi'::text,'görünmeyecek'::text,'görünmedi'::text,'Başparmaklarını kaldırmasaydı video bu kadar samimi görünmezdi.'::text),
(396585,44065,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem emelte volna fel a hüvelykujjait, a videó nem ... ilyen barátságosnak.'::text,'tűnt volna'::text,'fog tűnni'::text,'tűnt'::text,'Ha nem emelte volna fel a hüvelykujjait, a videó nem tűnt volna ilyen barátságosnak.'::text),
(396588,44066,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie bestritt, ihre Daumen zu nah vors Objektiv ...'::text,'gehalten zu haben'::text,'zu halten'::text,'gehalten'::text,'Sie bestritt, ihre Daumen zu nah vors Objektiv gehalten zu haben.'::text),
(396592,44066,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона заперечила, що ... пальці надто близько до об''єктива.'::text,'тримала'::text,'тримати'::text,'тримані'::text,'Вона заперечила, що тримала пальці надто близько до об''єктива.'::text),
(396591,44066,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negó ... los pulgares demasiado cerca del objetivo.'::text,'haber puesto'::text,'poner'::text,'puesto'::text,'Negó haber puesto los pulgares demasiado cerca del objetivo.'::text),
(396590,44066,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a nié ... ses pouces trop près de l''objectif.'::text,'avoir tenu'::text,'tenir'::text,'tenu'::text,'Elle a nié avoir tenu ses pouces trop près de l''objectif.'::text),
(396593,44066,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başparmaklarını objektife fazla yakın ... inkâr etti.'::text,'tuttuğunu'::text,'tutmayı'::text,'tutulmuş'::text,'Başparmaklarını objektife fazla yakın tuttuğunu inkâr etti.'::text),
(396594,44066,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy túl közel ... a hüvelykujjait az objektívhez.'::text,'tartotta'::text,'tartani'::text,'tartott'::text,'Tagadta, hogy túl közel tartotta a hüvelykujjait az objektívhez.'::text),
(396606,44068,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, angeblich hat sie ihren Bruder dazu gebracht, die Kamera für ihr Daumen-hoch ...'::text,'zu halten'::text,'halten'::text,'haltend'::text,'Rate mal, angeblich hat sie ihren Bruder dazu gebracht, die Kamera für ihr Daumen-hoch zu halten.'::text),
(396610,44068,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вгадай що, кажуть, вона вмовила брата ... камеру для її «клас».'::text,'потримати'::text,'потримати'::text,'тримання'::text,'Вгадай що, кажуть, вона вмовила брата потримати камеру для її «клас».'::text),
(396609,44068,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, al parecer consiguió que su hermano le ... la cámara para su pulgar arriba.'::text,'sujetara'::text,'sujetar'::text,'sujetando'::text,'Adivina qué, al parecer consiguió que su hermano le sujetara la cámara para su pulgar arriba.'::text),
(396608,44068,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment elle a fait ... la caméra à son frère pour son pouce levé.'::text,'tenir'::text,'tenir'::text,'tenant'::text,'Devine quoi, apparemment elle a fait tenir la caméra à son frère pour son pouce levé.'::text),
(396611,44068,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, güya başparmak pozu için kamerayı kardeşine ...'::text,'tutturmuş'::text,'tutturmuş'::text,'tutma'::text,'Bil bakalım, güya başparmak pozu için kamerayı kardeşine tutturmuş.'::text),
(396612,44068,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag rávette a bátyját, hogy ... a kamerát a hüvelykujj-pózához.'::text,'tartsa'::text,'tartsa'::text,'tartás'::text,'Képzeld, állítólag rávette a bátyját, hogy tartsa a kamerát a hüvelykujj-pózához.'::text),
(396615,44069,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Daumen hochgenommen, bevor die Kamera überhaupt lief. Eindeutig total entspannt dabei.'::text,'hatte'::text,'hat'::text,'nahm'::text,'Sie hatte die Daumen hochgenommen, bevor die Kamera überhaupt lief. Eindeutig total entspannt dabei.'::text),
(396619,44069,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... пальці вгору ще до того, як камера взагалі ввімкнулася. Явно дуже спокійна.'::text,'підняла'::text,'підняла'::text,'піднімала'::text,'Вона підняла пальці вгору ще до того, як камера взагалі ввімкнулася. Явно дуже спокійна.'::text),
(396618,44069,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... los pulgares arriba antes de que la cámara empezara a grabar. Claramente muy tranquila.'::text,'Había puesto'::text,'Ha puesto'::text,'Estaba poniendo'::text,'Había puesto los pulgares arriba antes de que la cámara empezara a grabar. Claramente muy tranquila.'::text),
(396617,44069,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les pouces avant même que la caméra démarre. Clairement très calme.'::text,'avait levé'::text,'a levé'::text,'levait'::text,'Elle avait levé les pouces avant même que la caméra démarre. Clairement très calme.'::text),
(396620,44069,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera daha başlamadan başparmaklarını ..., belli ki çok sakin.'::text,'kaldırmıştı'::text,'kaldırdı'::text,'kaldırıyordu'::text,'Kamera daha başlamadan başparmaklarını kaldırmıştı, belli ki çok sakin.'::text),
(396621,44069,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már azelőtt ... a hüvelykujjait, hogy a kamera egyáltalán elindult. Nyilván teljesen nyugodt.'::text,'feltartotta'::text,'feltartotta'::text,'tartotta fel'::text,'Már azelőtt feltartotta a hüvelykujjait, hogy a kamera egyáltalán elindult. Nyilván teljesen nyugodt.'::text),
(377040,41894,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schreib ihm heute Abend nicht, Bro, er ... bis 3 Uhr morgens, kein Witz.'::text,'programmiert'::text,'programmiert'::text,'programmiert'::text,'Schreib ihm heute Abend nicht, Bro, er programmiert bis 3 Uhr morgens, kein Witz.'::text),
(377044,41894,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не пиши йому сьогодні ввечері, бро, він ... до третьої ночі, без жартів.'::text,'програмуватиме'::text,'запрограмує'::text,'програмує'::text,'Не пиши йому сьогодні ввечері, бро, він програмуватиме до третьої ночі, без жартів.'::text),
(377043,41894,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No le escribas esta noche, bro, ... hasta las 3 de la mañana, en serio.'::text,'estará programando'::text,'programará'::text,'programa'::text,'No le escribas esta noche, bro, estará programando hasta las 3 de la mañana, en serio.'::text),
